
.story-manager {
  margin-top: 16px;
  padding: 18px;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  background: var(--surface-inset);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}
.manager-heading,
.published-row,
.manager-actions,
.credentials {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}
h3,
h4,
p {
  margin: 0;
}
h3,
h4 {
  font-weight: 600;
}
.manager-heading p,
.repository-note,
.manager-note,
small {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.9;
}
.manager-note,
.repository-note,
[role='status'],
[role='alert'] {
  margin-top: 10px;
}
a {
  color: var(--gold);
}
button,
input,
textarea,
select {
  font: inherit;
  color: inherit;
}
button {
  padding: 10px 12px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  background: var(--button-bg);
  color: var(--gold);
  cursor: pointer;
}
button:disabled {
  opacity: 0.45;
  cursor: default;
}
button:hover:not(:disabled) {
  background: var(--button-hover);
}
.credentials {
  margin-top: 14px;
  align-items: flex-end;
}
.credentials label {
  flex: 1;
  min-width: 0;
}
label {
  display: grid;
  gap: 6px;
  font-size: 13px;
}
input,
textarea,
select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--line-subtle);
  border-radius: 4px;
  background: var(--surface);
}
textarea {
  resize: vertical;
  line-height: 1.8;
}
.manager-error {
  color: var(--semantic-danger);
  line-height: 1.8;
}
.published-stories,
form {
  margin-top: 20px;
  border-top: 1px solid var(--line-subtle);
  padding-top: 16px;
}
.published-stories article {
  padding-block: 10px;
  border-bottom: 1px solid var(--line-subtle);
}
small {
  margin-left: 8px;
}
.manager-actions {
  justify-content: flex-start;
}
.withdraw-confirm {
  margin-top: 10px;
  line-height: 1.9;
}
.withdraw-confirm button {
  margin: 8px 8px 0 0;
}
fieldset {
  display: grid;
  min-width: 0;
  gap: 14px;
  margin: 14px 0 0;
  padding: 0;
  border: 0;
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 110px;
  gap: 12px;
}
.story-preview {
  display: grid;
  gap: 10px;
  margin-top: 16px;
  padding: 16px;
  border: 1px solid var(--line-subtle);
  line-height: 1.9;
}
.story-preview small {
  margin: 0;
  color: var(--gold);
}
@media (max-width: 650px) {
  .story-manager {
    padding: 14px 10px;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .credentials {
    display: grid;
    grid-template-columns: 1fr;
  }
}
@media (pointer: coarse) {
  input,
  textarea,
  select {
    font-size: 16px;
  }
}
