
.peace-panel {
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: var(--text-primary);

  &::before {
    content: '';
    position: absolute;
    width: min(64vw, 680px);
    aspect-ratio: 1;
    border-radius: 50%;
    border: 1px solid color-mix(in srgb, var(--jade) 12%, transparent);
    box-shadow:
      0 0 0 64px color-mix(in srgb, var(--line-subtle) 14%, transparent),
      0 0 0 132px color-mix(in srgb, var(--gold) 4%, transparent);
    opacity: 0.45;
    pointer-events: none;
  }
}

.peace-shell {
  position: relative;
  z-index: 1;
  width: min(100%, 1020px);
  display: grid;
  gap: 18px;
}

.peace-masthead {
  text-align: center;
}

.masthead-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--text-secondary);
  font-size: 11px;
  letter-spacing: 0.14em;

  span {
    width: 44px;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--gold-soft));

    &:last-child {
      transform: scaleX(-1);
    }
  }
}

.trib-surface {
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-lg, 14px);
  background:
    linear-gradient(125deg, color-mix(in srgb, var(--surface-raised) 78%, transparent), transparent 68%),
    var(--choice-surface, color-mix(in srgb, var(--reading-surface) 92%, transparent));
  box-shadow:
    0 12px 30px color-mix(in srgb, var(--stage-shadow) 18%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 54%, transparent);
}

.omen-sanctum {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(240px, 0.85fr);
  align-items: stretch;
  gap: 22px;
  padding: 22px 24px;
  border-color: color-mix(in srgb, var(--jade) 28%, var(--line-subtle));
  background:
    radial-gradient(circle at 12% 50%, color-mix(in srgb, var(--jade) 10%, transparent), transparent 46%),
    linear-gradient(125deg, color-mix(in srgb, var(--surface-raised) 82%, transparent), transparent 70%),
    var(--choice-surface);

  &.recovery {
    border-color: color-mix(in srgb, var(--semantic-warning) 34%, var(--line-subtle));
    background:
      radial-gradient(circle at 12% 50%, color-mix(in srgb, var(--semantic-warning) 11%, transparent), transparent 46%),
      var(--choice-surface);
  }

  &.critical {
    border-color: color-mix(in srgb, var(--semantic-danger) 42%, var(--line-subtle));
    background:
      radial-gradient(circle at 12% 50%, color-mix(in srgb, var(--semantic-danger) 12%, transparent), transparent 46%),
      var(--choice-surface);
  }
}

.omen-hero-main {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 20px;
}

.omen-compass {
  --compass-tone: var(--jade);

  position: relative;
  width: 86px;
  height: 86px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px dashed color-mix(in srgb, var(--compass-tone) 42%, var(--line-subtle));
  background: radial-gradient(circle, color-mix(in srgb, var(--compass-tone) 14%, transparent), transparent 72%);

  &.recovery {
    --compass-tone: var(--semantic-warning);
  }
  &.critical {
    --compass-tone: var(--semantic-danger);
  }

  .compass-ring {
    width: 64px;
    height: 64px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1px solid color-mix(in srgb, var(--compass-tone) 54%, var(--line-strong));
    background:
      radial-gradient(circle at 38% 32%, color-mix(in srgb, var(--compass-tone) 22%, transparent), transparent 68%),
      color-mix(in srgb, var(--surface-inset) 88%, transparent);
    color: var(--compass-tone);
    font-size: 24px;
    box-shadow:
      0 0 22px color-mix(in srgb, var(--compass-tone) 18%, transparent),
      inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 50%, transparent);
  }

  .compass-tick {
    position: absolute;
    left: 50%;
    width: 6px;
    height: 6px;
    border: 1px solid var(--gold);
    background: var(--surface-raised);
    transform: translateX(-50%) rotate(45deg);

    &.is-top {
      top: -4px;
    }
    &.is-bottom {
      bottom: -4px;
    }
  }
}

.omen-copy {
  min-width: 0;
  display: grid;
  gap: 6px;

  h2 {
    margin: 0;
    color: var(--text-primary);
    font:
      700 24px 'Noto Serif SC',
      'Songti SC',
      STSong,
      serif;
    letter-spacing: 0.05em;
    line-height: 1.25;
  }

  p {
    margin: 0;
    color: var(--text-secondary);
    font-size: 12.8px;
    line-height: 1.65;
  }
}

.omen-kicker-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.omen-seal-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 9px;
  border: 1px solid color-mix(in srgb, var(--jade) 36%, var(--line-subtle));
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--jade) 10%, transparent);
  color: var(--jade);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;

  .seal-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: currentColor;
    box-shadow: 0 0 7px currentColor;
  }
}

.omen-sanctum.recovery .omen-seal-pill {
  border-color: color-mix(in srgb, var(--semantic-warning) 42%, var(--line-subtle));
  background: color-mix(in srgb, var(--semantic-warning) 12%, transparent);
  color: var(--semantic-warning);
}

.omen-sanctum.critical .omen-seal-pill {
  border-color: color-mix(in srgb, var(--semantic-danger) 46%, var(--line-subtle));
  background: color-mix(in srgb, var(--semantic-danger) 12%, transparent);
  color: var(--semantic-danger);
}

.cooldown-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  color: var(--text-secondary);
  font-size: 10.5px;
}

.omen-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}

.omen-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 12px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-inset) 78%, transparent);
  color: var(--text-accent);
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;

  &.is-primary {
    border-color: color-mix(in srgb, var(--jade) 46%, var(--line-strong));
    background: color-mix(in srgb, var(--jade) 12%, var(--surface-inset));
    color: var(--jade);
  }

  &.is-gold {
    border-color: color-mix(in srgb, var(--gold) 52%, var(--line-strong));
    background: color-mix(in srgb, var(--gold) 14%, var(--surface-inset));
    color: var(--gold);
  }

  &:hover:not(:disabled) {
    border-color: var(--gold);
    color: var(--gold);
    background: var(--button-active);
    transform: translateY(-1px);
  }

  &:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
}

.omen-telemetry {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  padding-left: 20px;
  border-left: 1px solid color-mix(in srgb, var(--line-subtle) 82%, transparent);
}

.telemetry-row {
  display: grid;
  gap: 3px;
}

.telemetry-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 10.5px;

  i {
    color: var(--gold);
    font-size: 10px;
  }
}

.telemetry-val {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;

  strong {
    color: var(--text-primary);
    font-size: 13px;
    font-weight: 600;
  }

  small {
    color: var(--gold-soft);
    font-size: 11px;
    font-variant-numeric: tabular-nums;
  }
}

.danger-chip {
  padding: 1px 8px;
  border-radius: var(--radius-pill, 999px);
  font-style: normal;
  font-size: 10.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;

  &.danger-low {
    color: var(--jade);
    background: color-mix(in srgb, var(--jade) 12%, transparent);
  }
  &.danger-mid {
    color: var(--semantic-warning);
    background: color-mix(in srgb, var(--semantic-warning) 14%, transparent);
  }
  &.danger-high {
    color: var(--semantic-danger);
    background: color-mix(in srgb, var(--semantic-danger) 14%, transparent);
  }
}

.burden-section {
  display: grid;
  gap: 11px;
}

.section-heading {
  display: flex;
  align-items: center;
  gap: 10px;
}

.heading-title {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-accent);
  font:
    600 15px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  letter-spacing: 0.04em;

  i {
    color: var(--gold);
    font-size: 13px;
  }
}

.heading-rule {
  flex: 1;
  min-width: 20px;
  height: 1px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--gold) 28%, var(--line-subtle)), transparent);
}

.heading-summary {
  color: var(--text-secondary);
  font-size: 11.5px;
}

.burden-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.burden-card {
  --vital-color: var(--jade);

  position: relative;
  overflow: hidden;
  display: grid;
  gap: 10px;
  padding: 15px 16px;
  border-radius: var(--radius-md, 12px);
  border-color: color-mix(in srgb, var(--vital-color) 28%, var(--line-subtle));
  background:
    radial-gradient(circle at 96% 8%, color-mix(in srgb, var(--vital-color) 10%, transparent), transparent 44%),
    var(--choice-surface);

  &.tone-steady {
    --vital-color: var(--tier-mystic, var(--semantic-info));
  }
  &.tone-strained {
    --vital-color: var(--semantic-warning);
  }
  &.tone-critical {
    --vital-color: var(--semantic-danger);
  }

  .card-watermark {
    position: absolute;
    right: -6px;
    bottom: -8px;
    font-size: 56px;
    color: var(--vital-color);
    opacity: 0.06;
    pointer-events: none;
  }
}

.burden-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.burden-title-group {
  display: flex;
  align-items: center;
  gap: 9px;

  > div {
    display: grid;
    gap: 1px;
  }
}

.burden-emblem {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--vital-color) 38%, transparent);
  background: color-mix(in srgb, var(--vital-color) 11%, var(--surface-raised));
  color: var(--vital-color);
  font-size: 14px;
}

.burden-name {
  color: var(--text-primary);
  font-size: 13.5px;
  font-weight: 600;
}

.burden-domain {
  color: var(--text-secondary);
  font-size: 10px;
}

.burden-status-pill {
  padding: 2px 8px;
  border: 1px solid color-mix(in srgb, var(--vital-color) 34%, transparent);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--vital-color) 11%, transparent);
  color: var(--vital-color);
  font-size: 10.5px;
  font-weight: 600;
}

.burden-value {
  color: var(--vital-color);
  font:
    700 18px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  letter-spacing: 0.04em;
}

.burden-meter {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;

  .meter-seg {
    height: 4px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--line-subtle) 80%, transparent);

    &.filled {
      background: var(--vital-color);
      box-shadow: 0 0 8px color-mix(in srgb, var(--vital-color) 36%, transparent);
    }
  }
}

.aftermath-grid {
  display: grid;
  gap: 12px;
}

.result-section,
.residual-section,
.tribulation-result {
  padding: 15px 18px;
  border-radius: var(--radius-md, 12px);
  display: grid;
  gap: 8px;
}

.result-section {
  border-left: 3px solid var(--gold);
}

.result-badge {
  margin-left: auto;
  padding: 2px 10px;
  border: 1px solid color-mix(in srgb, var(--gold) 36%, transparent);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--gold) 11%, transparent);
  color: var(--gold);
  font-size: 11px;
}

.ledger-line {
  display: grid;
  grid-template-columns: 40px 1fr;
  gap: 8px;
  margin: 0;
  color: var(--text-secondary);
  font-size: 12.5px;

  small {
    color: var(--gold);
  }
}

.result-list > small {
  color: var(--gold);
}

.result-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.result-list span {
  padding: 3px 9px;
  border-radius: var(--radius-pill, 999px);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--semantic-danger) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 24%, transparent);
  font-size: 11px;
}

.result-list.aftermath span {
  background: color-mix(in srgb, var(--gold) 10%, transparent);
  border-color: color-mix(in srgb, var(--gold) 26%, transparent);
}

.residual-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.residual-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border-radius: var(--radius-pill, 999px);
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 28%, var(--line-subtle));
  background: color-mix(in srgb, var(--semantic-danger) 10%, transparent);
  font-size: 11.5px;

  b {
    color: var(--text-primary);
  }
  em {
    font-style: normal;
    color: var(--text-secondary);
  }
}

.tribulation-result strong {
  color: var(--text-primary);
  font-size: 14px;
}

.tribulation-result p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12.5px;
  line-height: 1.65;
}

.advice-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 13px 18px;
  border-radius: var(--radius-md, 12px);
  border-left: 3px solid color-mix(in srgb, var(--gold) 68%, var(--line-strong));
}

.advice-stamp {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid color-mix(in srgb, var(--gold) 32%, var(--line-subtle));
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--gold) 10%, transparent);
  color: var(--gold);
  font-size: 11.5px;
  font-weight: 600;
  white-space: nowrap;
}

.advice-prose {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12.8px;
  line-height: 1.68;
}

@media (max-width: 820px) {
  .omen-sanctum {
    grid-template-columns: 1fr;
    gap: 16px;
    padding: 16px;
  }

  .omen-telemetry {
    padding-left: 0;
    padding-top: 14px;
    border-left: 0;
    border-top: 1px solid color-mix(in srgb, var(--line-subtle) 82%, transparent);
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
  }
}

@media (max-width: 640px) {
  .peace-shell {
    gap: 14px;
  }

  .omen-hero-main {
    grid-template-columns: 1fr;
    justify-items: start;
    gap: 12px;
  }

  .omen-compass {
    width: 68px;
    height: 68px;

    .compass-ring {
      width: 50px;
      height: 50px;
      font-size: 19px;
    }
  }

  .omen-telemetry,
  .burden-grid {
    grid-template-columns: 1fr;
  }

  .advice-card {
    grid-template-columns: 1fr;
    justify-items: start;
    gap: 8px;
    padding: 12px 14px;
  }
}
