
.journey-panel {
  margin: 0 0 28px;
  padding: 4px 0 24px;
  border-bottom: 1px solid var(--line-subtle);
  color: var(--text-primary);
  overflow-wrap: anywhere;
}
.journey-heading {
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line-subtle);
}
.journey-picker {
  margin-top: 16px;
}
.picker-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  border-bottom: 1px solid var(--line-subtle);
}
.picker-tabs button {
  padding: 10px 4px;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-family: 'Noto Serif SC', 'Songti SC', STSong, serif;
  cursor: pointer;
}
.picker-tabs button[aria-pressed='true'] {
  color: var(--gold);
  border-bottom-color: var(--gold-soft);
}
.journey-heading,
.current-heading,
.seeking-controls,
.saved-journey-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
h2,
h3,
p {
  margin: 0;
}
h2 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 7px;
  font:
    600 18px 'Noto Serif SC',
    STSong,
    serif;
}
h2 i,
.eyebrow,
.field-caption,
.journey-field-label {
  color: var(--gold-soft);
}
h3 {
  font:
    600 17px 'Noto Serif SC',
    STSong,
    serif;
  line-height: 1.6;
  letter-spacing: 0.035em;
}
.eyebrow {
  font-size: 12px;
  letter-spacing: 0.12em;
}
.journey-intro,
.journal-empty {
  margin-top: 14px;
  color: var(--text-secondary);
  line-height: 1.9;
  font-size: 13px;
}
button,
select,
textarea {
  font: inherit;
  color: inherit;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: default;
  opacity: 0.45;
}
.quiet-button,
.journey-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 13px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: transparent;
  font-size: 12px;
  line-height: 1.5;
}
.journey-button {
  border-color: color-mix(in srgb, var(--gold) 40%, var(--line-subtle));
  background: color-mix(in srgb, var(--gold) 4%, transparent);
  color: var(--gold);
}
button:hover:not(:disabled) {
  background: var(--button-hover);
}
button:focus-visible,
summary:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
.seeking-surface {
  margin-top: 18px;
  padding: 18px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-md, 10px);
  background: var(--choice-surface, color-mix(in srgb, var(--surface-inset) 65%, transparent));
}
.field-label {
  display: grid;
  gap: 8px;
  font-size: 13px;
  color: var(--text-secondary);
}
textarea {
  width: 100%;
  box-sizing: border-box;
  padding: 10px 12px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-sm, 8px);
  background: var(--surface);
  color: var(--text-primary);
  resize: vertical;
  line-height: 1.8;
}
.seeking-controls {
  margin-top: 12px;
  font-size: 12px;
}
.seeking-controls label {
  display: flex;
  align-items: center;
  gap: 8px;
}
select {
  padding: 7px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-sm, 6px);
  background: var(--surface-raised);
}
.seeking-note,
.journey-error {
  margin-top: 12px;
  font-size: 13px;
  line-height: 1.8;
}
.seeking-note {
  color: var(--text-secondary);
}
.journey-error {
  color: var(--semantic-danger);
}
.proposal-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}
.proposal {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 18px 14px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--gold) 6%, transparent), transparent 65%),
    var(--choice-surface, color-mix(in srgb, var(--surface-inset) 65%, transparent));
  overflow-wrap: anywhere;
}
.proposal .eyebrow {
  font-size: 11px;
}
.proposal p {
  font-size: 13px;
  line-height: 1.9;
  color: var(--text-secondary);
}
.proposal .proposal-goal {
  color: var(--text-primary);
}
.proposal-goal span,
.field-caption {
  margin-right: 8px;
  font-size: 12px;
}
.proposal > button {
  margin-top: auto;
}
.current-journey {
  margin-top: 20px;
  padding: 22px 18px;
  background: linear-gradient(
    120deg,
    color-mix(in srgb, var(--gold) 7%, var(--choice-surface)),
    var(--choice-surface)
  );
  border: 1px solid color-mix(in srgb, var(--gold) 20%, var(--line-subtle));
  border-radius: var(--radius-md, 10px);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 52%, transparent);
}
.current-heading h3 {
  margin-top: 7px;
  color: var(--gold);
  font-size: 21px;
}
.journey-state,
.guess-state {
  font-size: 12px;
  color: var(--gold);
}
.journey-state {
  padding: 3px 10px;
  border: 1px solid color-mix(in srgb, var(--gold) 25%, transparent);
  border-radius: var(--radius-pill, 999px);
}
.longing {
  margin-top: 16px;
  line-height: 1.9;
  font-size: 14px;
}
.origin {
  margin-top: 12px;
  padding-left: 12px;
  border-left: 1px solid color-mix(in srgb, var(--gold) 35%, transparent);
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.9;
}
summary {
  cursor: pointer;
}
.origin p {
  margin-top: 7px;
}
.journey-progress,
.journey-next {
  display: grid;
  grid-template-columns: 4em minmax(0, 1fr);
  gap: 12px;
  margin-top: 14px;
  font-size: 13px;
  line-height: 1.9;
}
.journey-field-label {
  font-size: 12px;
  white-space: nowrap;
}
.journey-field-copy {
  min-width: 0;
}
.journey-next {
  padding-left: 12px;
  border-left: 2px solid color-mix(in srgb, var(--gold) 35%, transparent);
}
.journey-progress {
  color: var(--text-secondary);
}
.journey-controls,
.journey-links,
.clue-tags {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 14px;
}
.journey-controls {
  padding-top: 12px;
  border-top: 1px solid color-mix(in srgb, var(--line-subtle) 60%, transparent);
}
.journey-links button {
  border: 0;
  background: transparent;
  color: var(--text-secondary);
  padding: 3px 0;
  font-size: 12px;
}
.journal {
  margin-top: 22px;
  border-top: 1px solid var(--line-subtle);
}
.journal-tabs {
  display: flex;
  gap: 22px;
  padding-top: 10px;
}
.journal-tabs button {
  padding: 8px 0;
  border: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: var(--text-secondary);
  font-size: 13px;
  font-family: 'Noto Serif SC', 'Songti SC', STSong, serif;
}
.journal-tabs button[aria-pressed='true'] {
  color: var(--gold);
  border-bottom-color: var(--gold-soft);
}
.journal-tabs button > span {
  margin-left: 7px;
  font-size: 11px;
}
.journal-entry {
  padding: 16px 0;
  border-bottom: 1px solid var(--line-subtle);
  font-size: 13px;
  line-height: 1.9;
  overflow-wrap: anywhere;
}
.journal-entry p {
  margin-top: 6px;
}
.journal-entry details,
.journal-entry small,
.entry-source {
  color: var(--text-secondary);
  font-size: 12px;
}
.clue-selector {
  display: flex;
  align-items: center;
  gap: 9px;
  cursor: pointer;
}
input[type='checkbox'] {
  accent-color: var(--gold);
}
.guess-form {
  display: grid;
  gap: 10px;
  margin-top: 14px;
}
.guess-form > button {
  justify-self: start;
}
.clue-tags {
  margin-top: 8px;
  color: var(--text-secondary);
  font-size: 12px;
}
.clue-tags > span {
  border-bottom: 1px dotted var(--line-strong);
}
.journal-entry > button {
  margin-top: 10px;
}
.saved-journeys {
  margin-top: 18px;
  font-size: 12px;
  color: var(--text-secondary);
}
.saved-journeys > summary {
  padding: 8px 0;
  color: var(--text-primary);
  font-family: 'Noto Serif SC', 'Songti SC', STSong, serif;
}
.saved-journey {
  margin-top: 12px;
  padding: 12px;
  border-left: 1px solid var(--line-subtle);
  background: linear-gradient(90deg, color-mix(in srgb, var(--surface-inset) 40%, transparent), transparent);
}
.saved-journey strong {
  color: var(--text-primary);
  font-weight: 500;
  font-family: 'Noto Serif SC', 'Songti SC', STSong, serif;
  font-size: 14px;
}
.saved-journey small {
  margin-left: 10px;
}
.saved-hint {
  margin-top: 12px;
  line-height: 1.8;
}
.saved-journey-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.clear-record {
  color: var(--semantic-danger);
}
.cleanup-confirm {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 35%, var(--line-subtle));
  border-radius: 5px;
  background: var(--surface-inset);
  line-height: 1.9;
}
.cleanup-confirm p + p {
  margin-top: 6px;
}
@media (max-width: 850px) {
  .proposal-grid {
    grid-template-columns: 1fr;
  }
}
@media (pointer: coarse) {
  textarea {
    font-size: 16px;
  }
  button,
  select,
  .clue-selector {
    min-height: 44px;
  }
}
@media (max-width: 440px) {
  .current-journey,
  .seeking-surface {
    padding: 16px 12px;
  }
  .journey-heading {
    align-items: flex-start;
  }
}
