
.tribulation-view {
  position: relative;
  display: grid;
  place-items: center;
  color: var(--text-primary);
}

.trib-shell {
  width: min(100%, 1020px);
  display: grid;
  gap: 16px;
}

.trib-masthead {
  text-align: center;
}

.masthead-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--trib-color);
  font-size: 11px;
  letter-spacing: 0.14em;

  span {
    width: 44px;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--trib-color));

    &:last-child {
      transform: scaleX(-1);
    }
  }
}

.trib-surface {
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-lg, 14px);
  background:
    linear-gradient(125deg, color-mix(in srgb, var(--surface-raised) 78%, transparent), transparent 68%),
    var(--choice-surface, var(--surface));
  box-shadow:
    0 12px 30px color-mix(in srgb, var(--stage-shadow) 18%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 54%, transparent);
}

.trib-hero {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 20px;
  padding: 22px 24px;
  border-color: color-mix(in srgb, var(--trib-color) 38%, var(--line-subtle));
  background:
    radial-gradient(circle at 12% 50%, color-mix(in srgb, var(--trib-color) 14%, transparent), transparent 48%),
    var(--choice-surface);
}

.trib-crest {
  width: 84px;
  height: 84px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px dashed color-mix(in srgb, var(--trib-color) 46%, var(--line-subtle));
  background: radial-gradient(circle, color-mix(in srgb, var(--trib-color) 16%, transparent), transparent 72%);

  .crest-ring {
    width: 62px;
    height: 62px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1px solid color-mix(in srgb, var(--trib-color) 58%, var(--line-strong));
    background: color-mix(in srgb, var(--surface-inset) 88%, transparent);
    color: var(--trib-color);
    font-size: 24px;
    box-shadow: 0 0 22px color-mix(in srgb, var(--trib-color) 24%, transparent);
  }
}

.trib-hero-copy {
  min-width: 0;
  display: grid;
  gap: 7px;

  h2 {
    margin: 0;
    color: var(--text-primary);
    font:
      700 23px 'Noto Serif SC',
      'Songti SC',
      STSong,
      serif;
    letter-spacing: 0.05em;
  }

  p {
    margin: 0;
    color: var(--text-secondary);
    font-size: 13px;
    line-height: 1.68;
  }
}

.trib-pills {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.trib-type-pill,
.trib-level-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 10px;
  border-radius: var(--radius-pill, 999px);
  font-size: 11px;
  font-weight: 600;
}

.trib-type-pill {
  border: 1px solid color-mix(in srgb, var(--trib-color) 42%, transparent);
  background: color-mix(in srgb, var(--trib-color) 13%, transparent);
  color: var(--trib-color);
}

.trib-level-pill {
  border: 1px solid color-mix(in srgb, var(--trib-level-color) 42%, transparent);
  background: color-mix(in srgb, var(--trib-level-color) 12%, transparent);
  color: var(--trib-level-color);
}

.trib-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
}

.trib-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 0 12px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-inset) 80%, transparent);
  color: var(--text-accent);
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;

  &.is-primary {
    border-color: color-mix(in srgb, var(--trib-color) 48%, var(--line-strong));
    background: color-mix(in srgb, var(--trib-color) 14%, var(--surface-inset));
    color: var(--trib-color);
  }

  &:hover:not(:disabled) {
    border-color: var(--gold);
    color: var(--gold);
    background: var(--button-active);
  }

  &:disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
}

.trib-metrics-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.trib-metric-card,
.protection-card {
  padding: 16px 18px;
  border-radius: var(--radius-md, 12px);
  display: grid;
  gap: 11px;
}

.metric-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;

  > span {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: var(--text-accent);
    font-size: 13.5px;
    font-weight: 600;

    i {
      color: var(--gold);
    }
  }

  strong {
    color: var(--text-primary);
    font-size: 16px;
    font-variant-numeric: tabular-nums;

    small {
      color: var(--text-secondary);
      font-size: 11.5px;
      font-weight: 400;
    }
  }

  > small {
    color: var(--text-secondary);
    font-size: 11px;
  }
}

.wave-nodes {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;

  .wave-node {
    width: 24px;
    height: 24px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    border: 1px solid var(--line-subtle);
    background: color-mix(in srgb, var(--surface-inset) 70%, transparent);
    color: var(--text-secondary);
    font-size: 10.5px;
    font-variant-numeric: tabular-nums;

    b {
      font-weight: 600;
    }

    &.passed {
      border-color: color-mix(in srgb, var(--trib-color) 42%, transparent);
      color: var(--trib-color);
      background: color-mix(in srgb, var(--trib-color) 10%, transparent);
    }

    &.active {
      border-color: var(--trib-color);
      background: color-mix(in srgb, var(--trib-color) 22%, var(--surface-raised));
      color: var(--text-primary);
      box-shadow: 0 0 12px color-mix(in srgb, var(--trib-color) 38%, transparent);
    }
  }
}

.trib-progress-track,
.endurance-track {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--progress-bg);
}

.trib-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--trib-color) 70%, var(--gold)), var(--trib-color));
  transition: width 0.4s ease;
}

.trib-metric-card {
  --endurance-color: var(--jade);

  &.endurance-warn {
    --endurance-color: var(--semantic-warning);
  }
  &.endurance-danger {
    --endurance-color: var(--semantic-danger);
  }
}

.endurance-num {
  color: var(--endurance-color) !important;
}

.endurance-caption {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.endurance-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--endurance-color);
  transition: width 0.4s ease;
}

.protection-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.protection-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  background: color-mix(in srgb, var(--jade) 11%, var(--surface-inset));
  border: 1px solid color-mix(in srgb, var(--jade) 36%, var(--line-subtle));
  border-radius: var(--radius-pill, 999px);
  font-size: 12px;
  color: var(--jade);

  i {
    font-size: 10px;
  }
}

.cause-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 13px 18px;
  border-radius: var(--radius-md, 12px);
  border-left: 3px solid var(--trib-color);

  p {
    margin: 0;
    color: var(--text-secondary);
    font-size: 12.5px;
    line-height: 1.65;
  }
}

.cause-stamp {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid color-mix(in srgb, var(--trib-color) 36%, transparent);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--trib-color) 11%, transparent);
  color: var(--trib-color);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

@media screen and (max-width: 680px) {
  .trib-hero {
    grid-template-columns: 1fr;
    justify-items: start;
    padding: 16px;
  }

  .trib-metrics-grid {
    grid-template-columns: 1fr;
  }

  .cause-card {
    grid-template-columns: 1fr;
    justify-items: start;
    gap: 8px;
  }
}
