
.tab-nav-shell {
  position: relative;
  flex-shrink: 0;
  min-width: 0;
}

.tab-badge {
  display: inline-grid;
  min-width: 16px;
  height: 16px;
  place-items: center;
  padding: 0 4px;
  border: 1px solid color-mix(in srgb, var(--gold) 42%, transparent);
  border-radius: 999px;
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 10%, var(--tab-bg));
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-size: 9px;
  font-weight: 650;
  line-height: 1;
}

.tab-nav {
  position: relative;
  display: flex;
  padding: 5px 10px 4px;
  gap: 4px;
  background: var(--tab-bg);
  border-top: 1px solid var(--line-subtle);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  overscroll-behavior-x: contain;
  touch-action: pan-x pinch-zoom;

  &::-webkit-scrollbar {
    display: none;
  }

  .tab-btn {
    position: relative;
    flex: 1;
    min-width: 58px;
    min-height: 35px;
    padding: 5px 10px 6px;
    background: transparent;
    border: 1px solid transparent;
    border-radius: var(--radius-sm, 8px);
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition:
      background 0.18s ease,
      color 0.18s ease,
      border-color 0.18s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    white-space: nowrap;

    &:hover {
      background: var(--button-bg);
      color: var(--text-accent);
    }

    &.active {
      background: var(--tab-active);
      border-color: color-mix(in srgb, var(--gold) 24%, transparent);
      color: var(--gold);
      font-weight: 600;

      &::after {
        content: '';
        position: absolute;
        right: 26%;
        bottom: 2px;
        left: 26%;
        height: 2px;
        border-radius: 999px;
        background: linear-gradient(90deg, transparent, var(--gold) 18% 82%, transparent);
      }
    }
  }
}

.tab-scroll-control {
  position: absolute;
  z-index: 4;
  top: 50%;
  width: 28px;
  height: 32px;
  display: none;
  place-items: center;
  padding: 0;
  transform: translateY(-50%);
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  color: var(--gold);
  background: color-mix(in srgb, var(--surface-raised) 94%, transparent);
  box-shadow: 0 0 16px var(--stage-shadow);
  cursor: pointer;

  &.is-left {
    left: 4px;
  }
  &.is-right {
    right: 4px;
  }
}

// 手机端适配
@media screen and (max-width: 480px) {
  .tab-scroll-control {
    display: grid;
  }

  .tab-nav {
    padding: 3px 36px;
    gap: 2px;
    justify-content: flex-start;
    scroll-snap-type: x proximity;

    .tab-btn {
      flex: 0 0 auto;
      min-width: auto;
      min-width: 54px;
      padding: 5px 8px;
      font-size: 11px;
      gap: 3px;
      scroll-snap-align: center;

      i {
        font-size: 12px;
      }
    }
  }
}

// 超小屏幕适配
@media screen and (max-width: 360px) {
  .tab-nav {
    padding: 5px 34px;
    gap: 1px;

    .tab-btn {
      padding: 5px 8px;
      font-size: 10px;

      .tab-label {
        display: none;
      }

      i {
        font-size: 14px;
      }
    }
  }
}
