
.journey-trail {
  margin: 18px auto;
  padding: 9px 14px;
  border: 1px solid color-mix(in srgb, var(--gold) 22%, var(--line-subtle));
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(105deg, color-mix(in srgb, var(--gold) 7%, transparent), transparent 62%),
    var(--choice-surface, var(--surface-inset));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 48%, transparent);
  transition: border-color 0.16s ease, background 0.16s ease;

  &:hover {
    border-color: var(--line-strong);
    background:
      linear-gradient(105deg, color-mix(in srgb, var(--gold) 12%, transparent), transparent 68%),
      color-mix(in srgb, var(--gold) 5%, var(--choice-surface, var(--surface-inset)));
  }
}
.trail-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--gold);
  font: inherit;
  font-size: 12.5px;
  font-weight: 500;
  text-align: start;
  cursor: pointer;
}
.trail-heading > small {
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 400;
}
.trail-heading > i:last-child {
  margin-left: auto;
  opacity: 0.7;
}
p {
  margin: 5px 0 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.7;
}
