
.rarity-rank-sigil {
  flex: none;
  width: 12px;
  height: 12px;
  display: block;
}

.rarity-corner-ornament {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 1;
  width: 84px;
  height: 52px;
  color: var(--tier-color);
  pointer-events: none;
  opacity: 0.28;

  &[data-placement='bottom-right'] {
    top: auto;
    bottom: 0;
    right: 0;
    transform: scaleY(-1);
  }

  &[data-tier='earth'] {
    opacity: 0.26;
  }

  &[data-tier='heaven'] {
    opacity: 0.38;
  }

  &[data-tier='immortal'] {
    opacity: 0.5;
  }
}

.rarity-border-frame {
  --frame-inset-y: 3px;
  --frame-inset-left: 5px;
  --frame-inset-right: 3px;

  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
  color: var(--tier-color);

  &[data-tier='mystic'] {
    opacity: 0.52;
  }

  &[data-tier='earth'] {
    opacity: 0.72;
  }

  &[data-tier='heaven'] {
    opacity: 0.86;
  }

  &[data-tier='immortal'] {
    --frame-inset-left: 7px;
    opacity: 0.96;
  }

  &[data-style='peach'] {
    --frame-inset-y: 7px;
    --frame-inset-left: 8px;
    --frame-inset-right: 7px;
  }
}

.frame-corner {
  position: absolute;
  width: 20px;
  height: 20px;
  display: block;

  &.is-tl {
    top: var(--frame-inset-y);
    left: var(--frame-inset-left);
  }

  &.is-tr {
    top: var(--frame-inset-y);
    right: var(--frame-inset-right);
    transform: scaleX(-1);
  }

  &.is-bl {
    bottom: var(--frame-inset-y);
    left: var(--frame-inset-left);
    transform: scaleY(-1);
  }

  &.is-br {
    bottom: var(--frame-inset-y);
    right: var(--frame-inset-right);
    transform: scale(-1, -1);
  }
}

.frame-edge {
  position: absolute;
  left: 50%;
  width: 72px;
  height: 8px;
  display: block;
  transform: translateX(-50%);

  &.is-top {
    top: 1px;
  }

  &.is-bottom {
    bottom: 1px;
    transform: translateX(-50%) scaleY(-1);
  }
}

.frame-rail {
  position: absolute;
  height: 2px;
  width: clamp(44px, 22%, 108px);
  border-radius: 999px;
  opacity: clamp(0.32, calc(0.32 + 0.68 * var(--glow-scale, 1)), 1);

  &.is-top-left {
    top: 0;
    left: 22px;
    background: linear-gradient(90deg, var(--tier-color), color-mix(in srgb, var(--tier-color) 45%, #ffffff) 42%, transparent);
    box-shadow: 0 0 8px color-mix(in srgb, var(--tier-color) clamp(0%, calc(55% * var(--glow-scale, 1)), 100%), transparent);
  }

  &.is-bottom-right {
    bottom: 0;
    right: 22px;
    background: linear-gradient(270deg, var(--tier-color), color-mix(in srgb, var(--tier-color) 45%, #ffffff) 42%, transparent);
    box-shadow: 0 0 8px color-mix(in srgb, var(--tier-color) clamp(0%, calc(55% * var(--glow-scale, 1)), 100%), transparent);
  }
}

.frame-tape {
  position: absolute;
  width: 38px;
  height: 14px;
  display: block;
  filter: drop-shadow(0 1px 2px rgba(155, 85, 102, 0.14));

  &.is-tl {
    top: 3px;
    left: -8px;
    transform: rotate(-32deg);
  }

  &.is-br {
    bottom: 3px;
    right: -8px;
    transform: rotate(-32deg);
  }
}

@media screen and (max-width: 480px) {
  .rarity-corner-ornament {
    width: 68px;
    height: 42px;
  }

  .frame-corner {
    width: 16px;
    height: 16px;
  }

  .frame-edge {
    width: 54px;
  }

  .frame-tape {
    width: 32px;
    height: 12px;
  }
}
