
.affairs-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  margin-top: 12px;
}
button,
span {
  --link-tone: var(--gold);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  padding: 4px 8px;
  border-radius: 3px;
  font-size: 12px;
  line-height: 1.6;
  text-align: left;
  overflow-wrap: anywhere;
}
[data-kind='person'] {
  --link-tone: var(--semantic-relation);
}
[data-kind='place'] {
  --link-tone: var(--jade);
}
button {
  border: 1px solid color-mix(in srgb, var(--link-tone) 25%, var(--line-subtle));
  background: color-mix(in srgb, var(--link-tone) 4%, transparent);
  color: color-mix(in srgb, var(--link-tone) 65%, var(--text-primary));
  cursor: pointer;
}
button:hover {
  border-color: var(--link-tone);
}
button:focus-visible {
  outline: 2px solid var(--link-tone);
  outline-offset: 3px;
}
span {
  padding-inline: 2px;
  color: var(--text-secondary);
}
i {
  flex: none;
  color: var(--link-tone);
  font-size: 10px;
}
