
.gallery-panel {
  width: 100%;
  height: 100%;
  min-height: 0 !important;
  padding: 16px !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  container-type: size;

  .gallery-container {
    width: 100%;
    min-height: 0;
    flex: 1 1 auto;
    display: flex;
    flex-direction: row;
    align-items: safe center;
    justify-content: safe center;
    gap: 20px;
    overflow-x: auto;
    overflow-y: hidden;
    padding: 16px 0 10px;
    max-width: 100%;

    &::-webkit-scrollbar {
      height: 8px;
    }

    &::-webkit-scrollbar-track {
      background: var(--bg-secondary);
      border-radius: 4px;
    }

    &::-webkit-scrollbar-thumb {
      background: var(--button-bg);
      border-radius: 4px;

      &:hover {
        background: var(--button-hover);
      }
    }
  }

  .gallery-card {
    --gallery-portrait-width: clamp(150px, min(48cqw, calc((100cqh - 48px) * 0.6667)), 540px);
    --gallery-control-rail-width: 43px;

    flex-shrink: 0;
    width: auto;
    perspective: 1000px;
    position: relative;
    display: flex;
    flex-direction: row;
    align-items: center;
    cursor: pointer;
  }

  .gallery-card::before {
    content: '';
    width: var(--gallery-control-rail-width);
    flex: 0 0 var(--gallery-control-rail-width);
    pointer-events: none;
  }

  .card-inner {
    position: relative;
    width: var(--gallery-portrait-width);
    flex: 0 0 var(--gallery-portrait-width);
    aspect-ratio: 2 / 3;
    transition: transform 0.6s ease;
    transform-style: preserve-3d;
    border-radius: var(--radius-md, 10px);
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5);
  }

  .gallery-card.flipped .card-inner {
    transform: rotateY(180deg);
  }

  .card-image-controls {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    margin-left: 8px;
    padding: 3px;
    border: 1px solid var(--line-subtle);
    border-radius: var(--radius-sm, 8px);
    background: var(--surface-inset);
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
    opacity: 0.76;
    transition:
      opacity 0.18s ease,
      transform 0.18s ease;
    backdrop-filter: blur(6px);
    cursor: default;

    button {
      width: 28px;
      height: 28px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border: 0;
      border-radius: 4px;
      background: transparent;
      color: var(--text-accent);
      cursor: pointer;
      transition:
        color 0.16s ease,
        background 0.16s ease;

      &:hover,
      &:focus-visible {
        color: var(--text-primary);
        background: var(--button-hover);
        outline: none;
      }
    }
  }

  .gallery-card:hover .card-image-controls,
  .gallery-card:focus-within .card-image-controls {
    opacity: 1;
    transform: translateX(1px);
  }

  .card-face {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: var(--radius-md, 10px);
    overflow: hidden;
    border: 2px solid var(--border-color);
  }

  .card-front {
    img {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .card-name-bar {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 12px;
      background: linear-gradient(to top, rgba(0, 0, 0, 0.85), transparent);
      color: #fff;
      font-size: 16px;
      font-weight: bold;
      text-align: center;
      text-shadow: 0 2px 6px rgba(0, 0, 0, 0.9);
    }
  }

  .card-back {
    transform: rotateY(180deg);
    background: var(--reading-surface);

    .back-content {
      width: 100%;
      height: 100%;
      position: relative;

      .back-image {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
      }

      .back-info-panel {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        padding: 20px 16px;
        background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.7) 50%, transparent 100%);
        text-align: center;

        .back-name {
          font-size: 18px;
          font-weight: bold;
          color: var(--jade);
          margin-bottom: 8px;
          text-shadow:
            0 0 15px rgba(100, 150, 255, 0.6),
            0 2px 4px rgba(0, 0, 0, 0.8);
        }

        .back-text {
          font-size: 14px;
          color: var(--text-accent);
          line-height: 1.6;
          font-style: italic;
          text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
        }
      }
    }
  }

  .empty-hint {
    text-align: center;
    padding: 20px;
    color: var(--text-secondary);
    font-style: italic;
  }
}

.portrait-fade-enter-active,
.portrait-fade-leave-active {
  transition: opacity 0.16s ease;
}

.portrait-fade-enter-from,
.portrait-fade-leave-to {
  opacity: 0;
}

// 手机端适配
@media screen and (max-width: 480px) {
  .gallery-panel {
    padding: 8px !important;

    .gallery-container {
      gap: 14px;
      padding: 8px 0 6px;
    }

    .gallery-card {
      --gallery-portrait-width: clamp(150px, min(72cqw, calc((100cqh - 82px) * 0.6667)), 310px);

      flex-direction: column;
    }

    .gallery-card::before {
      display: none;
    }

    .card-front {
      .card-name-bar {
        padding: 10px;
        font-size: 14px;
      }
    }

    .card-back {
      .back-content {
        .back-info-panel {
          padding: 16px 12px;

          .back-name {
            font-size: 15px;
          }

          .back-text {
            font-size: 12px;
          }
        }
      }
    }

    .card-image-controls {
      flex-direction: row;
      margin-top: 6px;
      margin-left: 0;

      button {
        width: 26px;
        height: 26px;
      }
    }

    .gallery-card:hover .card-image-controls,
    .gallery-card:focus-within .card-image-controls {
      transform: translateY(1px);
    }
  }
}

@media (hover: none) {
  .gallery-panel .card-image-controls {
    opacity: 0.9;
  }
}
