
.stage-header {
  position: relative;
  min-height: 58px;
  display: grid;
  grid-template-columns: minmax(0, max-content) minmax(0, 1fr) max-content;
  align-items: center;
  gap: 14px;
  padding: 6px 14px;
  border-bottom: 1px solid var(--line-subtle);
  background: var(--header-bg);
  box-shadow:
    0 4px 18px color-mix(in srgb, var(--stage-shadow) 28%, transparent),
    inset 0 -1px 0 color-mix(in srgb, var(--paper-highlight) 38%, transparent);
  overflow: visible;
  z-index: 15;

  &::after {
    content: '';
    position: absolute;
    right: 50%;
    bottom: -1px;
    width: 80px;
    height: 2px;
    transform: translateX(50%);
    background: linear-gradient(90deg, transparent, var(--gold), transparent);
    opacity: 0.5;
    pointer-events: none;
  }
}

.turn-cluster,
.turn-navigation,
.reading-mode-switch,
.stage-utilities {
  display: flex;
  align-items: center;
}

.turn-cluster {
  min-width: 0;
  gap: 9px;
}

.crane-mark {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  object-fit: contain;
  filter: drop-shadow(0 2px 6px var(--stage-shadow));
}

.turn-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.turn-kicker {
  color: var(--gold-soft);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 10px;
  letter-spacing: 0.06em;
  line-height: 1.1;
}

.turn-title-row {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;

  strong {
    max-width: 152px;
    overflow: hidden;
    color: var(--text-primary);
    font-size: 13px;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.turn-token-count {
  flex: none;
  padding: 1px 6px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-inset) 65%, transparent);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-size: 9px;
  line-height: 1.35;
}

.turn-navigation {
  flex: 0 0 auto;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-inset) 66%, transparent);

  button {
    width: 24px;
    height: 24px;
    display: grid;
    place-items: center;
    padding: 0;
    border: 0;
    border-radius: 50%;
    color: var(--text-secondary);
    background: transparent;
    cursor: pointer;
    transition: all 0.16s ease;

    &:hover:not(:disabled) {
      color: var(--gold);
      background: var(--button-hover);
    }
    &:disabled {
      opacity: 0.3;
      cursor: not-allowed;
    }
  }

  span {
    min-width: 34px;
    color: var(--text-secondary);
    font-size: 10px;
    text-align: center;
    font-variant-numeric: tabular-nums;
  }
}

.reading-mode-switch {
  flex: 0 0 auto;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-inset) 68%, transparent);

  button {
    height: 25px;
    padding: 0 9px;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    border: 0;
    border-radius: var(--radius-pill, 999px);
    color: var(--text-secondary);
    background: transparent;
    font-size: 11px;
    font-weight: 500;
    white-space: nowrap;
    cursor: pointer;
    transition: all 0.16s ease;

    i {
      font-size: 10px;
    }
    &:hover {
      color: var(--text-primary);
    }
    &.active {
      color: var(--gold);
      background: var(--button-active);
      box-shadow: 0 1px 6px color-mix(in srgb, var(--stage-shadow) 22%, transparent);
    }
  }
}

.scene-hud {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.scene-location {
  min-width: 0;
  max-width: 100%;
  display: grid;
  justify-items: center;
  gap: 1px;
  padding: 4px 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-pill, 999px);
  color: var(--text-primary);
  background: transparent;
  cursor: pointer;
  transition: all 0.18s ease;

  &:hover {
    border-color: var(--line-subtle);
    background: color-mix(in srgb, var(--surface-inset) 62%, transparent);

    .location-jump-hint {
      opacity: 0.9;
      transform: translateX(2px);
    }
  }

  strong {
    max-width: 100%;
    overflow: hidden;
    color: var(--gold);
    font-family: 'Songti SC', 'STSong', serif;
    font-size: 15px;
    text-overflow: ellipsis;
    white-space: nowrap;

    i:first-child {
      margin-right: 5px;
      color: var(--jade);
    }
    span {
      color: var(--text-accent);
      font-weight: 400;
    }
    b {
      padding: 0 5px;
      color: var(--text-secondary);
      font-weight: 400;
    }
  }
}

.scene-kicker {
  color: var(--text-secondary);
  font-size: 9px;
  letter-spacing: 0.08em;
}

.location-jump-hint {
  margin-left: 5px;
  color: var(--text-secondary);
  font-size: 10px;
  opacity: 0.45;
  transition: all 0.16s ease;
}

.scene-location-compact {
  display: none;
}

.world-time-pill {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  color: var(--text-accent);
  background: color-mix(in srgb, var(--surface-inset) 66%, transparent);
  font-size: 11px;
  white-space: nowrap;

  i.is-night {
    color: var(--gold);
  }
  i.is-day {
    color: var(--semantic-warning);
  }
}

.stage-utilities {
  min-width: 0;
  justify-content: flex-end;
  gap: 6px;
}

.hud-badges {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-right: 2px;
}

.danger-badge {
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--danger-color) 52%, transparent);
  border-radius: var(--radius-pill, 999px);
  color: var(--danger-color);
  background: color-mix(in srgb, var(--danger-color) 10%, transparent);
  font-size: 10px;
  font-weight: 600;
  white-space: nowrap;
}

.heaven-posture-badge {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 9px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  color: var(--text-accent);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
  font-size: 10px;
  white-space: nowrap;
  cursor: help;

  b {
    color: var(--text-secondary);
    font-weight: 400;
  }
  &.sense-顺遂 .posture-sense {
    color: var(--semantic-success);
  }
  &.sense-受挫 .posture-sense {
    color: var(--semantic-warning);
  }
  &.tier-低压 .posture-tier {
    color: var(--jade);
  }
  &.tier-常态 .posture-tier {
    color: var(--text-secondary);
  }
  &.tier-高压 .posture-tier {
    color: var(--gold);
  }
  &.tier-极压 .posture-tier {
    color: var(--semantic-danger);
  }
  .posture-trend {
    font-size: 9px;
    &.is-up {
      color: var(--semantic-danger);
    }
    &.is-down {
      color: var(--jade);
    }
  }
  .posture-tooltip {
    position: absolute;
    z-index: 45;
    top: calc(100% + 8px);
    right: 0;
    width: max-content;
    max-width: 240px;
    padding: 8px 11px;
    display: grid;
    gap: 3px;
    border: 1px solid var(--line-strong);
    border-radius: var(--radius-sm, 8px);
    color: var(--text-primary);
    background: color-mix(in srgb, var(--surface-raised) 97%, transparent);
    box-shadow: 0 12px 28px var(--stage-shadow);
    font-size: 10px;
    line-height: 1.5;
    white-space: normal;
    overflow-wrap: anywhere;
    opacity: 0;
    pointer-events: none;
    transform: translateY(-3px);
    transition: all 0.16s ease;

    strong {
      color: var(--gold);
      font-size: 11px;
    }
    span {
      color: var(--text-secondary);
    }
  }
  &:hover .posture-tooltip,
  &:focus-visible .posture-tooltip {
    opacity: 1;
    transform: translateY(0);
  }
}

.utility-pill {
  box-sizing: border-box;
  flex: 0 0 auto;
  height: 29px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  color: var(--text-accent);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
  font: inherit;
  font-size: 11px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.16s ease;

  i {
    color: var(--gold);
    font-size: 11px;
  }
  .trigger-caret {
    color: var(--text-secondary);
    font-size: 9px;
    transition: transform 0.18s ease;
    &.open {
      transform: rotate(180deg);
      color: var(--gold);
    }
  }
  &:hover:not(:disabled),
  &.active {
    border-color: var(--line-strong);
    color: var(--gold);
    background: var(--button-hover);
  }
  &.active {
    background: var(--button-active);
  }
  &:disabled {
    opacity: 0.34;
    cursor: not-allowed;
  }
}

.stage-enter-pill {
  border-color: color-mix(in srgb, var(--jade) 48%, var(--line-strong));
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 12%, var(--surface-inset));
  i {
    color: var(--jade);
  }
}

.opening-pick-pill {
  border-color: color-mix(in srgb, var(--gold) 52%, var(--line-strong));
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 13%, var(--surface-inset));
  i {
    color: var(--gold);
  }
  &:hover:not(:disabled) {
    border-color: var(--gold);
    background: var(--button-hover);
  }
}

.icon-only-pill {
  width: 29px;
  padding: 0;
}

.tool-menu-group {
  position: relative;
  flex: 0 0 auto;
}

.compact-only-modes,
.compact-only-appearance {
  display: none;
}

.tool-popover {
  position: absolute;
  z-index: 50;
  top: calc(100% + 9px);
  right: 0;
  width: 224px;
  padding: 6px;
  display: grid;
  gap: 3px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-md, 12px);
  background: color-mix(in srgb, var(--surface-raised) 97%, transparent);
  backdrop-filter: var(--stage-blur, blur(14px));
  box-shadow:
    0 16px 40px color-mix(in srgb, var(--stage-shadow) 68%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--text-primary) 6%, transparent);
}

.popover-item {
  width: 100%;
  min-height: 40px;
  padding: 5px 8px;
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm, 8px);
  color: var(--text-primary);
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: all 0.15s ease;

  &:hover:not(:disabled) {
    background: var(--button-hover);
    border-color: color-mix(in srgb, var(--line-subtle) 80%, transparent);
  }
  &.active {
    border-color: color-mix(in srgb, var(--gold) 44%, var(--line-subtle));
    background: var(--button-active);
  }
  &.is-danger {
    .item-icon {
      color: var(--semantic-danger);
      background: color-mix(in srgb, var(--semantic-danger) 12%, transparent);
    }
    .item-copy strong {
      color: var(--semantic-danger);
    }
  }
  &:disabled {
    opacity: 0.38;
    cursor: not-allowed;
  }
}

.item-icon {
  width: 27px;
  height: 27px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: var(--radius-sm, 7px);
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 11%, var(--surface-inset));
  font-size: 12px;
}

.item-copy {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 1px;

  strong {
    color: var(--text-primary);
    font-size: 12px;
    font-weight: 600;
  }
  small {
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 10px;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.mode-switch-icon {
  flex: none;
  margin-left: auto;
  color: var(--text-secondary);
  font-size: 16px;
  &.is-on {
    color: var(--jade);
  }
}

.popover-divider {
  height: 1px;
  margin: 3px 6px;
  background: linear-gradient(90deg, transparent, var(--line-subtle), transparent);
}

.tool-popover-enter-active,
.tool-popover-leave-active {
  transition:
    opacity 120ms ease,
    transform 120ms ease;
  transform-origin: top right;
}
.tool-popover-enter-from,
.tool-popover-leave-to {
  opacity: 0;
  transform: translateY(-4px) scale(0.97);
}

.delete-dialog-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 18px;
  background: color-mix(in srgb, var(--stage-shadow) 72%, transparent);
  backdrop-filter: blur(5px);
}
.delete-dialog {
  width: min(420px, 100%);
  padding: 20px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 42%, var(--line-strong));
  border-radius: var(--radius-md, 12px);
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 97%, transparent);
  box-shadow: 0 24px 68px var(--stage-shadow);
}
.delete-dialog-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 40%, transparent);
  border-radius: 50%;
  color: var(--semantic-danger);
  background: color-mix(in srgb, var(--semantic-danger) 10%, var(--surface-inset));
}
.delete-dialog-copy h2 {
  margin: 0 0 6px;
  color: var(--text-accent);
  font-size: 15px;
}
.delete-dialog-copy p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.7;
}
.delete-dialog-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 8px;

  button {
    min-height: 34px;
    padding: 0 14px;
    border: 1px solid var(--line-subtle);
    border-radius: var(--radius-sm, 8px);
    color: var(--text-secondary);
    background: var(--surface-inset);
    cursor: pointer;
  }
  .confirm-delete {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    border-color: color-mix(in srgb, var(--semantic-danger) 46%, var(--line-subtle));
    color: var(--text-primary);
    background: color-mix(in srgb, var(--semantic-danger) 18%, var(--surface-inset));
    &:hover:not(:disabled) {
      color: #fff;
      background: var(--semantic-danger);
    }
  }
}

.stage-header.status-summary-bar {
  display: flex;
  min-height: 40px;
  gap: 6px;
  padding: 4px 10px;

  .utility-pill {
    height: 27px;
    padding: 0 8px;
  }
}

.status-summary {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 0;
  border: 0;
  color: var(--text-secondary);
  background: transparent;
  font: inherit;
  font-size: 11px;
  text-align: left;
  cursor: pointer;

  strong {
    color: var(--gold);
  }
  > * {
    flex-shrink: 0;
    white-space: nowrap;
  }
  i {
    margin-right: 3px;
  }
  .summary-realm {
    max-width: 85px;
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--jade);
  }
  .summary-location {
    flex: 1 1 50px;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

@container bright-stage (max-width: 1160px) {
  .immersion-pill .immersion-label {
    display: none;
  }
  .immersion-pill {
    width: 29px;
    padding: 0;
  }
}

@container bright-stage (max-width: 980px) {
  .reading-mode-switch {
    display: none;
  }
  .compact-only-modes {
    display: contents;
  }
}

@container bright-stage (max-width: 760px) {
  .stage-header {
    min-height: 54px;
    grid-template-columns: minmax(0, 1fr) minmax(0, 2fr) minmax(0, 1fr);
    gap: 6px;
    padding: 6px 8px;
    z-index: 40 !important;
  }
  .world-time-pill,
  .hud-badges,
  .crane-mark,
  .turn-copy,
  .scene-kicker,
  .scene-location-full,
  .appearance-pill,
  .turn-navigation span,
  .utility-pill .pill-label,
  .native-status-header .turn-cluster {
    display: none;
  }
  .compact-only-appearance {
    display: flex;
  }
  .scene-hud {
    grid-column: 2;
    min-width: 0;
    justify-content: center;
  }
  .scene-location {
    min-width: 0;
    padding: 4px 6px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .scene-location-compact {
    min-width: 0;
    max-width: 100%;
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 14px;
    span {
      min-width: 0;
      overflow: hidden;
      color: var(--gold);
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }
  .stage-utilities {
    grid-column: 3;
    gap: 4px;
  }
  .utility-pill {
    height: 31px;
    min-width: 31px;
    padding: 0 7px;
  }
  .stage-header.status-summary-bar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 2fr) minmax(0, 1fr);
    align-items: flex-start;
    .status-summary {
      grid-column: 2;
      > :not(.summary-location) {
        display: none;
      }
      .summary-location {
        padding-top: 4px;
        color: var(--gold);
        font-size: 13px;
        text-align: center;
      }
    }
    .tool-menu-group {
      display: flex;
      flex-direction: column;
      align-items: flex-end;
    }
    .tool-popover {
      position: relative;
      top: auto;
      right: auto;
      margin-top: 8px;
    }
  }
}
