
.journey-reference {
  margin-top: 16px;
  padding-top: 13px;
  border-top: 1px solid var(--line-subtle);
  font-size: 12px;
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}
p {
  margin: 0;
}
.reference-counts,
.reference-range,
.history-selector,
.history-pages,
.reference-details > summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 14px;
}
.reference-counts {
  line-height: 1.8;
}
.reference-counts i {
  margin-right: 6px;
}
.reference-details {
  margin-top: 12px;
}
.reference-details > summary {
  justify-content: space-between;
  padding: 8px 0;
  color: var(--text-primary);
  cursor: pointer;
}
.reference-details > summary i {
  margin-right: 8px;
  color: var(--gold-soft);
}
.reference-mode {
  color: var(--gold-soft);
  font-size: 11px;
}
.reference-hint {
  margin: 8px 0 12px;
  line-height: 1.8;
}
.reference-error {
  margin-top: 8px;
  line-height: 1.8;
  color: var(--semantic-danger, var(--danger));
}
.reference-range {
  margin: 12px 0;
  gap: 8px;
}
.reference-range label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
button,
input {
  color: inherit;
  font: inherit;
}
.reference-range input {
  box-sizing: border-box;
  width: 5.5em;
  padding: 7px 5px;
  border: 1px solid var(--line-subtle);
  border-radius: 3px;
  background: var(--surface);
  color: var(--text-primary);
}
button {
  padding: 7px 10px;
  border: 1px solid var(--line-subtle);
  border-radius: 3px;
  background: transparent;
  cursor: pointer;
}
button:hover:not(:disabled) {
  background: var(--button-hover);
  color: var(--gold);
}
button:disabled,
input:disabled {
  cursor: default;
  opacity: 0.45;
}
button:focus-visible,
input:focus-visible,
summary:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
.history-list {
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}
.history-row {
  padding: 11px 10px;
  border-top: 1px solid var(--line-subtle);
}
.history-row.row-selected {
  background: color-mix(in srgb, var(--gold) 3%, transparent);
}
.history-selector {
  gap: 7px 10px;
  cursor: pointer;
  line-height: 1.8;
}
.history-selector input {
  margin: 0;
  accent-color: var(--gold);
}
.history-name {
  color: var(--text-primary);
}
.history-selector small {
  color: var(--gold-soft);
  font-size: 10px;
}
.history-content {
  margin: 6px 0 0 24px;
  line-height: 1.8;
}
.history-content > summary {
  cursor: pointer;
}
.history-content p {
  margin-top: 10px;
  white-space: pre-wrap;
  color: var(--text-primary);
}
.history-pages {
  justify-content: center;
  margin-top: 14px;
}
@media (max-width: 440px) {
  .reference-counts {
    display: grid;
    gap: 2px;
  }
  .history-row {
    padding: 10px 6px;
  }
  .history-content {
    margin-left: 0;
  }
}
@media (pointer: coarse) {
  button,
  .reference-range input,
  .history-selector,
  .reference-details > summary,
  .history-content > summary {
    min-height: 44px;
  }
  .reference-range input {
    font-size: 16px;
  }
}
