
.affairs-panel {
  padding: 20px;
  color: var(--text-primary);
}
.location-brief {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 24px 0;
  padding: 20px 0;
  border-top: 1px solid var(--line-subtle);
  border-bottom: 1px solid var(--line-subtle);
}
.brief-header {
  text-align: center;
}
.brief-label {
  font-size: 12px;
  color: var(--text-secondary);
  letter-spacing: 2px;
  margin-bottom: 8px;
}
.brief-title {
  font-size: 26px;
  font-weight: bold;
  color: var(--text-accent);
  margin-bottom: 6px;
  font-family: 'Songti SC', STSong, serif;
}
.brief-domain {
  font-size: 14px;
  color: var(--gold);
}
.brief-desc {
  text-align: center;
  padding: 16px 24px;
  line-height: 1.8;
  color: var(--text-secondary);
  font-size: 14px;
  background: var(--choice-surface, var(--surface-inset));
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-md, 10px);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 48%, transparent);
}
.brief-desc i {
  color: var(--gold);
  opacity: 0.4;
  font-size: 12px;
  margin: 0 12px;
  vertical-align: super;
}
.brief-routes {
  margin-top: 8px;
}
.routes-title,
.connections-list {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}
.routes-title {
  margin-bottom: 12px;
  font-size: 13px;
  color: var(--text-secondary);
}
.routes-title i {
  color: var(--gold);
}
.connections-list {
  flex-wrap: wrap;
}
.connections-list button {
  padding: 6px 16px;
  background: var(--bg-primary);
  border: 1px solid var(--line-subtle);
  border-radius: 20px;
  font-size: 13px;
  color: var(--text-primary);
  cursor: pointer;
}
.connections-list i {
  margin-right: 8px;
  color: var(--gold);
  font-size: 11px;
}

.ledger-section {
  margin-bottom: 28px;
}
h2 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-subtle);
  color: var(--text-accent);
  font:
    600 18px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  letter-spacing: 0.06em;
}
h2 i {
  color: var(--gold);
  font-size: 15px;
}
h2 > span {
  margin-left: auto;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0;
}
.ledger-card {
  padding: 16px;
  margin-bottom: 12px;
  border: 1px solid color-mix(in srgb, var(--line-subtle) 80%, transparent);
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(115deg, color-mix(in srgb, var(--gold) 5%, transparent), transparent 64%),
    var(--choice-surface, color-mix(in srgb, var(--surface-inset) 62%, transparent));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 50%, transparent);
  overflow-wrap: anywhere;
}
.ledger-card.tracked {
  border-left: 3px solid color-mix(in srgb, var(--gold) 72%, var(--line-strong));
  background: linear-gradient(
    115deg,
    color-mix(in srgb, var(--gold) 10%, var(--choice-surface)),
    var(--choice-surface)
  );
}
.ledger-card.tracked h3 {
  color: var(--gold);
}
.ledger-card:focus {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
.ledger-card header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  margin-bottom: 10px;
}
h3 {
  flex: 1 1 150px;
  min-width: 0;
  margin: 0;
  font:
    600 16px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  line-height: 1.6;
  letter-spacing: 0.035em;
}
.type-label {
  flex: none;
  padding: 2px 9px;
  border: 1px solid color-mix(in srgb, var(--gold) 28%, transparent);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--gold) 9%, transparent);
  color: var(--gold);
  font-size: 11px;
  white-space: nowrap;
}
.ledger-card p {
  margin: 7px 0;
  font-size: 13px;
  line-height: 1.85;
  color: var(--text-secondary);
}
.ledger-card .task-goal {
  color: var(--text-primary);
}
.task-progress,
.task-next,
.event-change {
  display: grid;
  grid-template-columns: 3em minmax(0, 1fr);
  gap: 10px;
}
.ledger-field-label {
  color: var(--gold);
  font-size: 12px;
  padding-top: 1px;
  white-space: nowrap;
}
.ledger-field-copy {
  min-width: 0;
}
.ledger-card .task-next {
  margin-top: 12px;
  padding-left: 11px;
  border-left: 2px solid color-mix(in srgb, var(--gold) 35%, transparent);
  color: var(--text-primary);
}
.track-button {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  padding: 4px 10px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  color: var(--text-secondary);
  background: transparent;
  font-size: 11px;
  line-height: 1.5;
  cursor: pointer;
}
.track-button[aria-pressed='true'] {
  border-color: color-mix(in srgb, var(--gold) 40%, transparent);
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 5%, transparent);
}
footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 12px;
}
footer :deep(.affairs-links) {
  margin-top: 0;
}
footer > button,
.result-link {
  padding: 5px 0;
  border: 0;
  background: transparent;
  color: var(--gold);
  font-size: 12px;
  line-height: 1.6;
  text-align: left;
  cursor: pointer;
}
.intent-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 0;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--gold) 35%, transparent);
  background: transparent;
  color: var(--gold);
  font-size: 12px;
  line-height: 1.6;
  cursor: pointer;
}
footer > .intent-button {
  margin-left: auto;
}
button:focus-visible,
summary:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
button:hover:not(:disabled) {
  color: var(--text-accent);
}
.event-card {
  border-left-color: color-mix(in srgb, var(--jade) 40%, var(--line-subtle));
}
.event-card h3 {
  color: var(--jade);
}
.event-card.settled h3 {
  color: var(--text-secondary);
}
.event-status,
.event-origin,
small {
  font-size: 12px;
  color: var(--text-secondary);
}
.effects {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}
.effects span {
  font-size: 11px;
  color: var(--jade);
}
.result-card {
  padding: 12px 14px;
  border-width: 0 0 0 1px;
  border-radius: 0;
  background: transparent;
}
.result-card h3 {
  color: var(--text-primary);
  font-size: 15px;
}
.result-card .result-link {
  display: block;
  margin-top: 8px;
}
.empty-hint,
.calm-state {
  font-size: 13px;
  line-height: 1.9;
  color: var(--text-secondary);
  padding: 12px 0;
}
.ledger-section > .empty-hint,
.calm-state {
  margin: 8px 0;
  padding: 14px 16px;
  border-left: 1px solid var(--line-subtle);
  background: linear-gradient(90deg, color-mix(in srgb, var(--gold) 2%, transparent), transparent);
}
.calm-state p {
  margin: 0 0 8px;
}
.reputation-section {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--line-subtle);
  color: var(--text-secondary);
  font-size: 13px;
}
summary {
  cursor: pointer;
}
.reputation-section > summary {
  color: var(--text-primary);
  font-family: 'Noto Serif SC', 'Songti SC', STSong, serif;
}
.reputation-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 0;
}
button:disabled {
  opacity: 0.5;
  cursor: default;
}
@media (max-width: 600px) {
  .affairs-panel {
    padding: 12px;
  }
  .location-brief {
    margin-top: 16px;
  }
  .brief-desc {
    padding: 14px;
  }
  .ledger-card {
    padding: 14px 12px;
  }
  .ledger-card header {
    gap: 8px;
  }
  .ledger-card h3 {
    flex-basis: 100%;
  }
  .result-card {
    padding: 10px 12px;
  }
  footer > .intent-button {
    margin-left: 0;
  }
}
