
.cultivation-status {
  width: 100%;
  height: var(--stage-height);
  min-height: 0;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  position: relative;
  container: bright-stage / inline-size;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line-strong) 72%, transparent);
  border-radius: var(--radius-lg, 12px);
  color: var(--text-primary);
  isolation: isolate;
  background: var(--stage-canvas);
  box-shadow: 0 20px 60px var(--stage-shadow);
  transition:
    height 0.22s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
  font-family: 'Microsoft YaHei', 'PingFang SC', sans-serif;
  font-size: 13px;
}

.cultivation-status.pseudo-stage-fit {
  height: 100dvh;
}

.cultivation-status.detached-status {
  height: auto;
  max-width: 100%;
  box-shadow: 0 6px 22px var(--stage-shadow);

  @media screen and (min-width: 761px) {
    width: 94%;
  }

  .stage-main {
    flex: none;
    height: var(--status-panel-height);
    max-height: var(--status-panel-height);
  }
}

.cultivation-status.map-expanded {
  box-shadow: 0 24px 72px var(--stage-shadow);
}

.stage-backdrop,
.frame-overlay {
  position: absolute;
  inset: 0;
  z-index: 0;
  contain: paint;
  pointer-events: none;
}

.stage-backdrop {
  background:
    var(--theme-art) center / cover no-repeat,
    var(--stage-material);
  transition: background 0.28s ease;
}
.frame-overlay {
  inset: 0;
  background: var(--frame-material);
  opacity: 0.45;
}

.cultivation-status > :where(.stage-header, .stage-main, .stage-navigation, .command-dock) {
  position: relative;
  z-index: 1;
}
.cultivation-status > :deep(.stage-header) {
  z-index: 40;
}
.stage-navigation {
  display: contents;
}
.stage-main {
  min-height: 0;
  flex: 1;
  display: flex;
}
.stage-viewport {
  min-width: 0;
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  background: var(--stage-veil);
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
  transition: background 0.25s ease;
}
.stage-viewport.reading-mode {
  overflow: hidden;
  background: transparent;
}
.stage-viewport > :deep(.panel) {
  box-sizing: border-box;
  width: 100%;
  max-width: 1180px;
  min-height: 100%;
  margin: 0 auto;
  padding: 24px 28px;
  background: transparent;
}
.stage-viewport > :deep(.panel > section),
.stage-viewport > :deep(.panel > div) {
  border-color: var(--line-subtle);
}
.stage-viewport > :deep(*:not(.story-reader, .panel)) {
  color-scheme: dark;
}
.light-theme .stage-viewport > :deep(*:not(.story-reader, .panel)) {
  color-scheme: light;
}
.full-map-panel {
  max-width: none !important;
  height: 100%;
  min-height: 0;
  padding: 0 !important;
  display: flex;
  flex-direction: column;
}
.stage-viewport > :deep(.gallery-panel) {
  max-width: none !important;
  height: 100%;
}
.tribulation-panel {
  max-width: 1180px;
  margin: 0 auto;
  padding: 24px 28px !important;
}
@media screen and (max-width: 760px) {
  .stage-viewport > :deep(.panel),
  .tribulation-panel {
    padding: 14px 12px !important;
  }
}

.stage-viewport :deep(.section-title),
.stage-viewport :deep(.panel-title),
.stage-viewport :deep(.section-header),
.stage-viewport :deep(.panel-header) {
  color: var(--text-accent);
  border-color: var(--line-subtle);
}
.stage-viewport :deep(.section-title i),
.stage-viewport :deep(.panel-title i),
.stage-viewport :deep(.section-header i),
.stage-viewport :deep(.panel-header i) {
  color: var(--gold);
}
.stage-viewport :deep(.empty-hint),
.stage-viewport :deep(.empty-state),
.stage-viewport :deep(.no-data) {
  color: var(--text-secondary);
}
.stage-viewport :deep(.progress-bar),
.stage-viewport :deep(.progress-track) {
  background: var(--progress-bg);
}

.cultivation-status[data-view='cultivation'],
.cultivation-status[data-view='skills'] {
  --view-accent: var(--jade);
}
.cultivation-status[data-view='timeline'] {
  --view-accent: var(--gold);
}
.cultivation-status[data-view='inventory'],
.cultivation-status[data-view='map'] {
  --view-accent: var(--gold);
}
.cultivation-status[data-view='companions'],
.cultivation-status[data-view='gallery'] {
  --view-accent: var(--semantic-relation);
}
.cultivation-status[data-view='tribulation'] {
  --view-accent: var(--semantic-danger);
}
.cultivation-status[data-view='affairs'] {
  --view-accent: var(--semantic-info);
}

.cultivation-status:not([data-view='story']):not([data-view='timeline'])
  .stage-viewport::before {
  content: '';
  position: sticky;
  top: 0;
  z-index: 8;
  display: block;
  width: 100%;
  height: 2px;
  margin-bottom: -2px;
  background: linear-gradient(90deg, transparent, var(--view-accent, var(--gold)) 22% 78%, transparent);
  opacity: 0.38;
  pointer-events: none;
}

.cultivation-status[data-theme='lantern'] .frame-overlay {
  opacity: 0.36;
}
.cultivation-status[data-theme='lantern'] :deep(.tab-btn.active) {
  border-color: color-mix(in srgb, var(--gold) 28%, transparent);
  box-shadow:
    inset 0 calc(8px * var(--glow-scale, 1)) calc(20px * var(--glow-scale, 1))
      color-mix(in srgb, var(--gold) calc(11% * var(--glow-scale, 1)), transparent),
    0 0 calc(14px * var(--glow-scale, 1)) color-mix(in srgb, var(--gold) calc(5% * var(--glow-scale, 1)), transparent);
}
.cultivation-status[data-theme='lantern'] :deep(.primary-command:not(.stop)) {
  box-shadow:
    inset 0 0 calc(14px * var(--glow-scale, 1))
      color-mix(in srgb, var(--gold) calc(10% * var(--glow-scale, 1)), transparent),
    0 0 calc(12px * var(--glow-scale, 1)) color-mix(in srgb, var(--gold) calc(6% * var(--glow-scale, 1)), transparent);
}
.cultivation-status[data-theme='duskInk'] .frame-overlay {
  opacity: 0.34;
}
.cultivation-status[data-theme='shanhai'] {
  border-color: color-mix(in srgb, var(--jade) 68%, #132d2d);
  box-shadow:
    0 18px 48px var(--stage-shadow),
    inset 0 0 0 1px color-mix(in srgb, var(--gold) 18%, transparent);
}
.cultivation-status[data-theme='shanhai'] :deep(.story-copy) {
  text-shadow: none;
}
.cultivation-status[data-theme='shanhai'] :deep(textarea::-webkit-scrollbar-button) {
  display: none;
}
.cultivation-status[data-theme='peachPudding'] {
  border-color: rgba(226, 146, 166, 0.56);
  box-shadow:
    0 16px 46px rgba(166, 110, 104, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}
.cultivation-status[data-theme='peachPudding'] :deep(.story-copy) {
  text-shadow: none;
}
.cultivation-status[data-theme='peachPudding'] :deep(.crane-mark) {
  filter: drop-shadow(0 2px 5px rgba(190, 120, 130, 0.24)) saturate(0.86);
}
.cultivation-status[data-theme='peachPudding'] :deep(.stage-header) {
  border-bottom-color: rgba(224, 146, 166, 0.34);
  box-shadow:
    0 4px 16px rgba(166, 110, 104, 0.1),
    inset 0 -1px 0 rgba(255, 255, 255, 0.72);
}
.cultivation-status[data-theme='peachPudding'] :deep(.tab-btn.active),
.cultivation-status[data-theme='peachPudding'] :deep(.reading-mode-switch button.active),
.cultivation-status[data-theme='peachPudding'] :deep(.interaction-segments button.active),
.cultivation-status[data-theme='peachPudding'] :deep(.primary-command:not(.stop)) {
  color: #5a3430;
  border-color: rgba(222, 132, 156, 0.52);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.78);
}
.cultivation-status[data-theme='peachPudding'] :deep(.tab-btn.active i),
.cultivation-status[data-theme='peachPudding'] :deep(.primary-command:not(.stop) i) {
  color: var(--gold);
}
.cultivation-status[data-theme='peachPudding']
  :deep(
    :is(
      .spirit-stone-balance,
      .ledger-card,
      .foundation-item,
      .trib-surface,
      .portrait-persona-card
    )
  ) {
  box-shadow:
    0 8px 22px rgba(176, 114, 118, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}
.cultivation-status[data-theme='starrailGlass'] {
  border-color: rgba(114, 186, 248, 0.38);
  box-shadow:
    0 22px 60px rgba(4, 8, 22, 0.62),
    inset 0 1px 0 rgba(214, 246, 255, 0.16);
}
.cultivation-status[data-theme='starrailGlass'] :deep(.stage-header)::after {
  width: 148px;
  background: linear-gradient(90deg, transparent, var(--jade), #b49bff, var(--gold), transparent);
  opacity: 0.72;
}
.cultivation-status[data-theme='starrailGlass'] :deep(.stage-header),
.cultivation-status[data-theme='starrailGlass'] :deep(.tab-nav),
.cultivation-status[data-theme='starrailGlass'] :deep(.command-dock) {
  box-shadow: inset 0 1px 0 rgba(214, 246, 255, 0.1);
}
.cultivation-status[data-theme='starrailGlass'] :deep(.tab-btn.active) {
  border-color: rgba(92, 225, 230, 0.38);
  color: var(--jade);
  box-shadow: inset 0 1px 0 rgba(214, 246, 255, 0.16);
}
.cultivation-status[data-theme='starrailGlass'] :deep(.tab-btn.active)::after {
  background: linear-gradient(90deg, transparent, var(--jade) 20%, #b49bff 80%, transparent);
}
.cultivation-status[data-theme='starrailGlass']
  :deep(
    :is(
      .spirit-stone-balance,
      .action-card,
      .ledger-card,
      .foundation-item,
      .trib-surface,
      .portrait-persona-card
    )
  ) {
  backdrop-filter: blur(10px);
  box-shadow:
    0 12px 28px rgba(4, 8, 24, 0.38),
    inset 0 1px 0 rgba(214, 246, 255, 0.2),
    inset 0 0 calc(24px * var(--glow-scale, 1)) rgba(92, 225, 230, calc(0.04 * var(--glow-scale, 1)));
}
.cultivation-status[data-theme='velvetOpera'] {
  border-color: rgba(232, 74, 111, 0.4);
  box-shadow:
    0 22px 60px rgba(5, 2, 8, 0.68),
    inset 0 1px 0 rgba(237, 208, 157, 0.16);
}
.cultivation-status[data-theme='velvetOpera'] .frame-overlay {
  opacity: 0.4;
}
.cultivation-status[data-theme='velvetOpera'] :deep(.stage-header)::after {
  width: 152px;
  background: linear-gradient(90deg, transparent, var(--jade), var(--gold), var(--jade), transparent);
  opacity: 0.75;
}
.cultivation-status[data-theme='velvetOpera'] :deep(.tab-btn.active) {
  border-color: rgba(232, 74, 111, 0.44);
  box-shadow:
    inset 0 1px 0 rgba(237, 208, 157, 0.18),
    inset 0 calc(-8px * var(--glow-scale, 1)) calc(18px * var(--glow-scale, 1))
      rgba(232, 74, 111, calc(0.14 * var(--glow-scale, 1)));
}
.cultivation-status[data-theme='velvetOpera'] :deep(.primary-command:not(.stop)) {
  border-color: rgba(237, 208, 157, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(237, 208, 157, 0.2),
    0 calc(4px * var(--glow-scale, 1)) calc(14px * var(--glow-scale, 1))
      rgba(232, 74, 111, calc(0.16 * var(--glow-scale, 1)));
}
.cultivation-status[data-theme='velvetOpera']
  :deep(
    :is(
      .spirit-stone-balance,
      .ledger-card,
      .foundation-item,
      .trib-surface,
      .portrait-persona-card
    )
  ) {
  box-shadow:
    0 12px 30px rgba(5, 2, 8, 0.42),
    inset 0 1px 0 rgba(237, 208, 157, 0.15);
}
.light-theme :deep(.portrait-backdrop-echo) {
  filter: blur(12px) saturate(0.92) brightness(0.98);
  opacity: 0.36;
}

.cultivation-status.immersive :deep(.stage-header) {
  border-bottom-color: var(--line-subtle);
}
.cultivation-status.reduce-motion,
.cultivation-status.reduce-motion :deep(*) {
  scroll-behavior: auto !important;
  animation: none !important;
  transition-duration: 0.01ms !important;
}

.cultivation-status.mobile-layout {
  transition: none;
}

.cultivation-status :deep(.story-copy .dhl-story-dialogue),
.cultivation-status :deep(.story-prose .dhl-story-dialogue) {
  color: var(--story-dialogue-color);
  font-family: inherit;
  font-weight: 600;
  letter-spacing: 0.015em;
}

.cultivation-status :deep(:is(.story-copy, .story-prose) .dhl-story-notice) {
  box-sizing: border-box;
  display: block;
  margin: 1.35em 0;
  padding: 0.8em 1em;
  border-block: 1px solid var(--line-subtle);
  border-inline-start: 2px solid color-mix(in srgb, var(--gold) 60%, var(--line-subtle));
  border-radius: 0 var(--radius-sm, 6px) var(--radius-sm, 6px) 0;
  background: linear-gradient(105deg, color-mix(in srgb, var(--gold) 8%, var(--choice-surface)), var(--choice-surface));
  color: var(--text-primary);
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  text-align: start;
  text-indent: 0;
  text-shadow: none;
  overflow-wrap: anywhere;
}

.cultivation-status :deep(.dhl-story-notice__heading) {
  display: flex;
  align-items: center;
  gap: 0.55em;
  margin-bottom: 0.3em;
  color: var(--gold);
  font-family: inherit;
  font-size: 0.86em;
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: 0.1em;
}

.cultivation-status :deep(.dhl-story-notice__mark) {
  flex: 0 0 auto;
  font-size: 0.95em;
  line-height: 1;
}

.cultivation-status :deep(.dhl-story-notice__body) {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  letter-spacing: inherit;
}

:deep(button:focus-visible),
:deep(input:focus-visible),
:deep(textarea:focus-visible),
:deep(summary:focus-visible) {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px var(--focus-ring);
}

@media screen and (max-width: 760px) {
  .cultivation-status {
    border-radius: var(--radius-sm, 6px);
    font-size: 13px;
    box-shadow: 0 10px 30px var(--stage-shadow);
  }
}
// Map browsing gets a compact shell without changing the reading layouts.
.cultivation-status.map-expanded[data-theme] :deep(.stage-header) {
  min-height: 44px;
  padding-top: 4px;
  padding-bottom: 4px;
  margin-top: 5px;
}
.map-expanded :deep(.scene-kicker),
.map-expanded :deep(.turn-copy > span) {
  display: none;
}
.map-expanded :deep(.crane-mark) {
  width: 28px;
  height: 28px;
}
.cultivation-status.map-expanded[data-theme] .stage-main {
  margin-top: 4px;
}
.map-expanded .stage-viewport {
  overflow: hidden;
}
.map-expanded :deep(.command-dock) {
  padding-top: 4px;
  padding-bottom: 4px;
}
@media (min-width: 1100px) {
  .map-expanded .stage-navigation {
    display: flex;
    flex: 0 0 auto;
    align-items: stretch;
    min-width: 0;
    margin: 0 10px;
    background: var(--tab-bg);
    border-top: 1px solid var(--line-strong);
    border-bottom: 1px solid var(--line-subtle);
  }
  .map-expanded .stage-navigation :deep(.tab-nav-shell) {
    flex: 1;
  }
  .cultivation-status.map-expanded[data-theme] .stage-navigation :deep(.tab-nav) {
    margin: 0;
    border: 0;
  }
  .map-expanded .stage-navigation :deep(.tab-nav) {
    height: 40px;
    padding: 2px 4px;
  }
  .map-expanded .stage-navigation :deep(.tab-btn) {
    min-height: 34px;
    padding: 4px 6px;
  }
}
