
.portrait-rail {
  position: relative;
  box-sizing: border-box;
  height: 100%;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
  padding: 10px 16px;
  overflow: hidden;
  border-left: 1px solid color-mix(in srgb, var(--line-subtle) 65%, transparent);
  background: var(--portrait-material), color-mix(in srgb, var(--stage-veil) 64%, transparent);
  box-shadow: inset 12px 0 28px color-mix(in srgb, var(--stage-shadow) 10%, transparent);

  &::before {
    content: '';
    position: absolute;
    inset: 10px 10px;
    border-radius: var(--radius-lg, 14px);
    border: 1px solid color-mix(in srgb, var(--line-subtle) 36%, transparent);
    pointer-events: none;
    opacity: 0.55;
  }

  &[data-ornament='peach']::before {
    border-style: dashed;
    border-color: color-mix(in srgb, var(--gold) 24%, var(--line-subtle));
    opacity: 0.68;
  }

  &[data-ornament='starrail']::before {
    border-color: color-mix(in srgb, var(--jade) 24%, var(--line-subtle));
    background: radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--jade) 7%, transparent), transparent 46%);
  }

  &[data-ornament='velvet']::before {
    border-color: color-mix(in srgb, var(--gold) 22%, var(--line-subtle));
    background: radial-gradient(circle at 50% 100%, color-mix(in srgb, var(--accent-color) 8%, transparent), transparent 48%);
  }
}

.portrait-rail > * {
  position: relative;
  z-index: 1;
}

.portrait-rail-ornament {
  flex: 1 1 18px;
  min-height: 0;
  max-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: color-mix(in srgb, var(--gold) 68%, var(--line-strong));
  pointer-events: none;
  overflow: hidden;
  transition: opacity 0.2s ease;

  svg {
    width: min(100%, 236px);
    height: 24px;
    flex-shrink: 0;
  }

  .ornament-accent {
    fill: var(--gold);
    opacity: 0.78;
  }

  .ornament-jade {
    fill: var(--jade);
    opacity: 0.68;
  }
}

.portrait-ensemble {
  flex: 0 1 auto;
  min-width: 0;
  min-height: 0;
  margin-block: auto;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.portrait-tabs {
  flex: none;
  display: flex;
  gap: 5px;
  overflow-x: auto;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }

  button {
    flex-shrink: 0;
    padding: 4px 10px;
    border: 1px solid var(--line-subtle);
    border-radius: 999px;
    color: var(--text-secondary);
    background: color-mix(in srgb, var(--surface-inset) 65%, transparent);
    font-size: 11px;
    cursor: pointer;
    transition: all 0.18s ease;

    &.active {
      border-color: color-mix(in srgb, var(--gold) 52%, var(--line-strong));
      color: var(--gold);
      background: var(--button-active);
    }
  }
}

.portrait-stage {
  position: relative;
  width: 100%;
  flex: 0 1 auto;
  min-width: 0;
  min-height: 180px;
  max-height: 100%;
  padding: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--gold) 32%, var(--line-subtle));
  border-radius: var(--radius-lg, 12px);
  background: var(--surface-inset);
  box-shadow:
    var(--card-shadow, 0 12px 30px rgba(0, 0, 0, 0.36)),
    inset 0 1px 0 color-mix(in srgb, var(--text-primary) 8%, transparent);

  .portrait-flip-surface {
    position: relative;
    z-index: 1;
    width: 100%;
    height: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    cursor: pointer;
    display: block;
  }

  img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center 14%;
  }

  &.is-landscape img {
    object-fit: contain;
    object-position: center;
  }

  &:hover .portrait-floating-tools {
    opacity: 1;
    transform: translateY(0);
  }
}

.portrait-backdrop-echo {
  position: absolute;
  inset: -10px;
  z-index: 0;
  background-position: center;
  background-size: cover;
  filter: blur(12px) saturate(0.86) brightness(0.56);
  opacity: 0.58;
  pointer-events: none;
}

.portrait-side-tag {
  position: absolute;
  z-index: 2;
  top: 10px;
  left: 10px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid color-mix(in srgb, var(--gold) 36%, var(--line-subtle));
  border-radius: 999px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--choice-surface) 90%, var(--surface-raised));
  font-size: 9px;
  letter-spacing: 0.06em;
  pointer-events: none;

  i {
    color: var(--gold);
  }
}

.portrait-floating-tools {
  position: absolute;
  z-index: 3;
  top: 9px;
  right: 9px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px;
  border: 1px solid color-mix(in srgb, var(--line-strong) 48%, var(--line-subtle));
  border-radius: 999px;
  background: color-mix(in srgb, var(--choice-surface) 88%, var(--surface-raised));
  opacity: 0.84;
  transform: translateY(-1px);
  transition: all 0.18s ease;

  button {
    width: 24px;
    height: 24px;
    display: grid;
    place-items: center;
    padding: 0;
    border: 0;
    border-radius: 50%;
    color: var(--text-primary);
    background: transparent;
    font-size: 10px;
    cursor: pointer;
    transition: all 0.15s ease;

    &:hover,
    &.active {
      color: var(--gold);
      background: var(--button-hover);
    }
  }
}

.portrait-caption {
  position: absolute;
  z-index: 2;
  right: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 40px 14px 11px;
  color: var(--text-primary);
  background: var(--portrait-scrim);
  text-align: left;
  pointer-events: none;

  small {
    color: var(--gold);
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.08em;
  }
  strong {
    font-family: 'Songti SC', 'STSong', serif;
    font-size: 18px;
    letter-spacing: 0.06em;
  }
}

.portrait-persona-card {
  flex: none;
  padding: 10px 12px;
  display: grid;
  gap: 7px;
  border: 1px solid var(--paper-border);
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--gold) 7%, transparent), transparent 60%),
    var(--choice-surface);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 55%, transparent);
}

.persona-tags {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  font-size: 10px;
}

.persona-relation {
  padding: 2px 7px;
  border: 1px solid color-mix(in srgb, var(--semantic-relation) 36%, var(--line-subtle));
  border-radius: 999px;
  color: var(--semantic-relation);
  background: color-mix(in srgb, var(--semantic-relation) 10%, transparent);
  font-weight: 600;
}

.persona-realm {
  padding: 2px 7px;
  border-radius: 999px;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 10%, transparent);
}

.persona-favor {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--gold);
  font-weight: 600;
  font-variant-numeric: tabular-nums;

  i {
    color: var(--semantic-relation);
    font-size: 9px;
  }
}

.persona-favor-track {
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--progress-bg) 88%, transparent);

  > span {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, var(--gold), var(--semantic-relation));
    transition: width 0.28s ease;
  }
}

.persona-mood {
  margin: 0;
  display: flex;
  align-items: baseline;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.55;

  i {
    flex: none;
    color: var(--gold-soft);
    font-size: 9px;
  }
  span {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    line-clamp: 3;
  }
}

.persona-promise {
  margin: 0;
  padding-top: 6px;
  border-top: 1px dashed color-mix(in srgb, var(--line-subtle) 78%, transparent);
  display: flex;
  align-items: baseline;
  gap: 6px;
  color: color-mix(in srgb, var(--text-accent) 88%, var(--text-secondary));
  font-size: 10.5px;
  line-height: 1.48;

  i {
    flex: none;
    color: var(--jade);
    font-size: 9px;
  }

  span {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }
}

.portrait-controls {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.talk-primary-btn {
  flex: 1;
  min-width: 0;
  height: 32px;
  padding: 0 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid color-mix(in srgb, var(--jade) 48%, var(--line-strong));
  border-radius: 999px;
  color: var(--jade);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--jade) 16%, transparent), transparent 75%),
    color-mix(in srgb, var(--surface-inset) 88%, transparent);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.18s ease;

  &:hover:not(:disabled) {
    border-color: var(--gold);
    color: var(--gold);
    background: var(--button-active);
  }
  &:disabled {
    opacity: 0.36;
    cursor: not-allowed;
  }
}

.companion-jump-btn {
  flex: none;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--semantic-relation) 34%, var(--line-subtle));
  border-radius: 50%;
  color: var(--semantic-relation);
  background: color-mix(in srgb, var(--surface-inset) 86%, transparent);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.16s ease;

  &:hover {
    border-color: var(--gold);
    color: var(--gold);
    background: var(--button-hover);
  }
}

.scroll-tool-group {
  display: inline-flex;
  align-items: center;
  padding: 2px;
  gap: 2px;
  border: 1px solid var(--line-subtle);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-inset) 84%, transparent);

  .candidate-counter {
    min-width: 28px;
    color: var(--text-secondary);
    font-size: 10px;
    text-align: center;
    font-variant-numeric: tabular-nums;
  }

  button {
    width: 26px;
    height: 26px;
    display: grid;
    place-items: center;
    border: 0;
    border-radius: 50%;
    color: var(--text-secondary);
    background: transparent;
    font-size: 11px;
    cursor: pointer;
    transition: all 0.16s ease;

    &:hover,
    &.active {
      color: var(--gold);
      background: var(--button-hover);
    }
  }
}

.portrait-shift-enter-active, .portrait-shift-leave-active { transition: opacity 0.16s ease; }
.portrait-shift-enter-from, .portrait-shift-leave-to { opacity: 0; }

@media screen and (max-height: 680px) and (min-width: 761px) {
  .portrait-rail-ornament {
    display: none;
  }
  .persona-promise {
    display: none;
  }
}

@media screen and (max-width: 760px) {
  .portrait-rail {
    height: 184px;
    display: block;
    padding: 10px 12px;
    border-bottom: 1px solid var(--line-subtle);
    border-left: 0;

    &::before {
      display: none;
    }
  }

  .portrait-rail-ornament {
    display: none;
  }

  .portrait-ensemble {
    height: 100%;
    margin-block: 0;
    display: grid;
    grid-template-columns: 124px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
    gap: 6px 10px;
  }

  .portrait-tabs {
    grid-column: 2;
    grid-row: 1;
    align-content: start;
  }
  .portrait-stage {
    grid-column: 1;
    grid-row: 1 / 4;
    height: 100%;
    min-height: 0;
    aspect-ratio: auto !important;
  }
  .portrait-persona-card {
    grid-column: 2;
    grid-row: 2;
    padding: 6px 8px;
    overflow: hidden;
  }
  .persona-favor-track,
  .persona-promise {
    display: none;
  }
  .portrait-controls {
    grid-column: 2;
    grid-row: 3;
    justify-content: flex-start;
  }
  .portrait-caption {
    padding: 30px 9px 8px;
  }
  .portrait-caption strong {
    font-size: 14px;
  }
}
