
.cloud-stories {
  margin-top: 16px;
}
.cloud-toolbar,
.cloud-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}
.cloud-toolbar {
  justify-content: space-between;
}
.cloud-toolbar p,
.cloud-note {
  margin: 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.9;
}
button {
  padding: 10px 13px;
  border: 1px solid var(--line-subtle);
  border-radius: 3px;
  background: color-mix(in srgb, var(--gold) 4%, transparent);
  color: var(--gold);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}
button:disabled {
  opacity: 0.45;
  cursor: default;
}
button:hover:not(:disabled) {
  background: var(--button-hover);
}
button:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
.cloud-note,
.cloud-error {
  margin-top: 14px;
  line-height: 1.9;
}
.cloud-error {
  color: var(--semantic-danger);
  font-size: 13px;
}
.cloud-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}
.cloud-story {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 18px 14px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--surface-inset) 65%, transparent), transparent);
  overflow-wrap: anywhere;
}
.story-genres,
.cloud-story p > span {
  color: var(--gold-soft);
  font-size: 12px;
}
.cloud-story h3,
.cloud-story p {
  margin: 0;
}
.cloud-story h3 {
  font:
    600 17px 'Noto Serif SC',
    STSong,
    serif;
  letter-spacing: 0.035em;
  line-height: 1.6;
}
.cloud-story p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.9;
}
.cloud-story .story-goal {
  color: var(--text-primary);
}
.cloud-story p > span {
  margin-right: 8px;
}
.cloud-story small {
  color: var(--text-secondary);
}
.cloud-story button {
  margin-top: auto;
}
@media (max-width: 650px) {
  .cloud-grid {
    grid-template-columns: 1fr;
  }
}
