
@use '../rarity-card' as rarity;

.skills-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  color: var(--text-primary);

  @include rarity.rarity-card-system('.skill-strip', '.skill-emblem', '.skill-rank', '.skill-name');

  &[data-theme='shanhai'],
  &[data-theme='peachPudding'] {
    .skill-desc {
      color: color-mix(in srgb, var(--text-primary) 88%, var(--text-secondary));
    }
  }

  &[data-theme-style='classic'] {
    .skill-desc {
      font-family: 'Noto Serif SC', 'Noto Sans SC', serif;
      font-weight: 500;
    }
  }
}

.skills-masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-subtle);
}

.masthead-title {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;

  h2 {
    margin: 0;
    display: inline-flex;
    align-items: center;
    gap: 9px;
    color: var(--text-accent);
    font:
      600 18px 'Noto Serif SC',
      'Songti SC',
      STSong,
      serif;
    letter-spacing: 0.06em;

    i {
      color: var(--gold);
      font-size: 15px;
    }
  }
}

.main-art-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border: 1px solid color-mix(in srgb, var(--jade) 32%, var(--line-subtle));
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--jade) 10%, var(--choice-surface));
  color: var(--jade);
  font-size: 11px;
  font-weight: 500;

  i {
    font-size: 10px;
  }
}

.masthead-stats {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.total-pill {
  padding: 3px 10px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-raised) 72%, transparent);
  color: var(--text-secondary);
  font-size: 11.5px;
}

.filter-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-inset) 65%, transparent);
  color: var(--text-secondary);
  font-size: 11.5px;
  cursor: pointer;
  transition: all 0.16s ease;

  span {
    opacity: 0.78;
    font-variant-numeric: tabular-nums;
  }

  &:hover {
    color: var(--text-primary);
    border-color: var(--line-strong);
  }

  &.active {
    color: var(--gold);
    border-color: color-mix(in srgb, var(--gold) 48%, var(--line-strong));
    background: var(--button-active);
    font-weight: 600;
  }
}

.skills-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.skill-strip {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  align-items: start;
  gap: 13px;
  padding: 14px 16px;
}

.skill-emblem {
  position: relative;
  z-index: 2;
  width: 36px;
  height: 36px;
  margin-top: 1px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--tier-color) 34%, transparent);
  border-radius: var(--radius-sm, 8px);
  color: var(--tier-color);
  font-size: 14px;
}

.skill-body {
  position: relative;
  z-index: 2;
  min-width: 0;
  display: grid;
  gap: 7px;
}

.skill-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.skill-title-group {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.skill-name {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.4;
  letter-spacing: 0.03em;
  color: var(--text-primary);
}

.skill-type {
  padding: 1px 7px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-raised) 68%, transparent);
  font-size: 11.5px;
  font-weight: 600;
  color: color-mix(in srgb, var(--text-primary) 82%, var(--text-secondary));
}

.skill-rank {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  border: 1px solid color-mix(in srgb, var(--tier-color) 36%, transparent);
  border-radius: var(--radius-pill, 999px);
  font-size: 11px;
  font-weight: 600;
  color: var(--tier-color);
  background: color-mix(in srgb, var(--tier-color) 12%, transparent);
  letter-spacing: 0.04em;
}

.skill-desc {
  margin: 0;
  font-family: 'Noto Sans SC', 'MiSans', 'PingFang SC', 'Microsoft YaHei UI', sans-serif;
  font-size: 13.6px;
  font-weight: 450;
  line-height: 1.74;
  color: color-mix(in srgb, var(--text-primary) 80%, var(--text-secondary));
}

.skill-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 2px;
}

.skill-proficiency {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-raised) 66%, transparent);
  border: 1px solid color-mix(in srgb, var(--line-subtle) 80%, transparent);
  font-size: 11.5px;
  font-weight: 600;
  color: color-mix(in srgb, var(--text-primary) 82%, var(--text-secondary));

  small {
    color: var(--text-secondary);
    font-size: 10px;
  }
}

.proficiency-pips {
  display: inline-flex;
  align-items: center;
  gap: 5px;

  .pip {
    width: 14px;
    height: 4px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--line-subtle) 82%, transparent);
    transition: background 0.2s ease;

    &.filled {
      background: var(--tier-color);
      box-shadow: 0 0 8px color-mix(in srgb, var(--tier-color) clamp(0%, calc(38% * var(--glow-scale, 1)), 100%), transparent);
    }
  }
}

.skill-strip:is(.rank-tier-mortal, .rank-tier-yellow) .proficiency-pips .pip.filled {
  box-shadow: none;
}

.skill-strip.rank-tier-immortal .proficiency-pips .pip.filled {
  background: linear-gradient(90deg, var(--tier-immortal), var(--tier-heaven));
  box-shadow: 0 0 10px color-mix(in srgb, var(--tier-immortal) clamp(0%, calc(42% * var(--glow-scale, 1)), 100%), transparent);
}

.empty-hint {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 36px 16px;
  border: 1px dashed var(--line-subtle);
  border-radius: var(--radius-md, 10px);
  background: color-mix(in srgb, var(--choice-surface) 55%, transparent);
  text-align: center;
  font-size: 12.5px;
  color: var(--text-secondary);

  i {
    color: var(--gold);
    font-size: 18px;
    opacity: 0.72;
  }
}

@media screen and (max-width: 480px) {
  .skills-list {
    gap: 10px;
  }

  .skill-strip {
    grid-template-columns: 32px minmax(0, 1fr);
    gap: 10px;
    padding: 11px 12px;
  }

  .skills-panel .skill-strip.rank-tier-immortal {
    padding-left: 15px;
  }

  .skill-emblem {
    width: 32px;
    height: 32px;
    font-size: 12px;
  }

  .skill-name {
    font-size: 15px;
  }

  .skill-desc {
    font-size: 12.5px;
  }
}
