
@use '../rarity-card' as rarity;

.inventory-panel {
  display: flex;
  flex-direction: column;
  gap: 22px;
  color: var(--text-primary);

  @include rarity.rarity-card-system('.item-strip', '.item-emblem', '.item-rank', '.item-name');

  &[data-theme-style] .item-strip:focus-visible {
    box-shadow: 0 0 0 2px var(--gold);
  }

  &[data-theme='shanhai'],
  &[data-theme='peachPudding'] {
    .item-desc {
      color: color-mix(in srgb, var(--text-primary) 88%, var(--text-secondary));
    }
  }

  &[data-theme-style='classic'] {
    .item-desc {
      font-family: 'Noto Serif SC', 'Noto Sans SC', serif;
      font-weight: 500;
    }
  }

  &[data-theme-style='peach'] .spirit-stone-balance:not(.is-empty) {
    border-radius: 14px;
    outline: 1px dashed color-mix(in srgb, var(--stone-color) 30%, transparent);
    outline-offset: -5px;

    .spirit-stone-emblem {
      border-radius: 9px;
      border-color: rgba(255, 255, 255, 0.9);
      background: color-mix(in srgb, var(--stone-color) 13%, #fff);
      box-shadow:
        inset 0 2px 0 rgba(255, 255, 255, 0.9),
        0 2px 6px color-mix(in srgb, var(--stone-color) 18%, transparent);
    }
  }

  &[data-theme-style='starrail'] .spirit-stone-balance:not(.is-empty) {
    background:
      linear-gradient(
        125deg,
        color-mix(in srgb, var(--stone-color) 14%, transparent),
        transparent 46%,
        rgba(214, 246, 255, 0.08) 72%,
        transparent
      ),
      var(--choice-surface, var(--surface-inset));
    box-shadow:
      0 10px 24px rgba(4, 8, 24, 0.36),
      inset 0 1px 0 rgba(214, 246, 255, 0.24),
      inset 0 0 18px color-mix(in srgb, var(--stone-color) clamp(0%, calc(10% * var(--glow-scale, 1)), 100%), transparent);

    .spirit-stone-emblem {
      border-color: color-mix(in srgb, var(--stone-color) 48%, rgba(214, 246, 255, 0.4));
      box-shadow:
        0 0 12px color-mix(in srgb, var(--stone-color) clamp(0%, calc(28% * var(--glow-scale, 1)), 100%), transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.36);
    }
  }
}

.inventory-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.section-title {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  font:
    700 17px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  letter-spacing: 0.05em;
  color: var(--text-accent);

  i {
    color: var(--gold);
    font-size: 14px;
  }
}

.section-rule {
  flex: 1;
  min-width: 24px;
  height: 1px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--gold) 28%, var(--line-subtle)), transparent);
}

.section-count {
  flex: none;
  padding: 2px 9px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-raised) 68%, transparent);
  color: var(--text-secondary);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.spirit-stone-valuation {
  min-width: 0;
}

.spirit-stone-summary {
  padding: 2px 0;
  border-radius: var(--radius-sm, 8px);
  list-style: none;
  cursor: pointer;

  &::-webkit-details-marker {
    display: none;
  }

  &:focus-visible {
    outline: 2px solid var(--gold);
    outline-offset: 4px;
  }

  .section-title {
    flex: none;
  }
}

.spirit-stone-tag {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  min-width: 0;
  padding: 4px 12px;
  border: 1px solid color-mix(in srgb, var(--gold) 34%, var(--line-subtle));
  border-radius: var(--radius-pill, 999px);
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--gold) 10%, transparent), transparent),
    color-mix(in srgb, var(--choice-surface) 88%, transparent);
  color: var(--gold);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  transition: border-color 160ms ease;

  strong {
    min-width: 0;
    font-weight: 600;
    overflow-wrap: anywhere;
  }
}

.spirit-stone-valuation-label {
  white-space: nowrap;
}

.spirit-stone-chevron {
  flex: none;
  width: 12px;
  height: 12px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 160ms ease;
}

.spirit-stone-valuation[open] {
  .spirit-stone-tag {
    border-color: color-mix(in srgb, var(--gold) 55%, transparent);
  }

  .spirit-stone-chevron {
    transform: rotate(180deg);
  }
}

.spirit-stone-conversion {
  margin-top: 10px;
  padding: 11px 14px;
  border: 1px solid color-mix(in srgb, var(--gold) 24%, var(--line-subtle));
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(100deg, color-mix(in srgb, var(--gold) 6%, transparent), transparent),
    var(--choice-surface);
}

.spirit-stone-rate {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 7px;
  margin: 0;
  color: var(--text-primary);
  font-size: 12px;
  line-height: 1.7;

  > span:not(.spirit-stone-equals) {
    white-space: nowrap;
  }
}

.spirit-stone-equals {
  color: var(--gold);
}

.spirit-stone-note {
  margin: 5px 0 0;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.7;
}

.spirit-stone-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.spirit-stone-balance {
  --stone-color: var(--jade-soft);
  --stone-tint: 8%;
  --stone-rim: 34%;

  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: 17px;
  min-width: 0;
  padding: 13px 14px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--stone-color) var(--stone-rim), var(--line-subtle));
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--stone-color) var(--stone-tint), transparent), transparent 62%),
    var(--choice-surface, var(--surface-inset));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 52%, transparent);
  transition:
    border-color 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease;

  &::before,
  &::after {
    position: absolute;
    z-index: -1;
    pointer-events: none;
    content: '';
  }

  &::before {
    right: -21px;
    bottom: -39px;
    width: 100px;
    aspect-ratio: 1;
    border: 1px solid color-mix(in srgb, var(--stone-color) 14%, transparent);
    background: linear-gradient(40deg, color-mix(in srgb, var(--stone-color) 3%, transparent), transparent 70%);
    transform: rotate(34deg);
  }

  &::after {
    top: 5px;
    left: 5px;
    width: 8px;
    height: 8px;
    border-top: 1px solid color-mix(in srgb, var(--stone-color) 40%, transparent);
    border-left: 1px solid color-mix(in srgb, var(--stone-color) 40%, transparent);
  }

  &[data-grade='中品灵石'] {
    --stone-color: var(--tier-mystic, var(--semantic-info));
  }

  &[data-grade='上品灵石'] {
    --stone-color: var(--tier-earth, #b88cff);
  }

  &[data-grade='极品灵石'] {
    --stone-color: var(--tier-heaven, var(--gold));
  }

  &.is-empty {
    --stone-tint: 3%;
    --stone-rim: 17%;

    box-shadow: none;

    &::before,
    &::after {
      opacity: 0.45;
    }

    .spirit-stone-emblem {
      background: color-mix(in srgb, var(--stone-color) 4%, transparent);
    }

    .spirit-stone-name,
    .spirit-stone-count {
      color: var(--text-secondary);
    }

    .spirit-stone-count {
      text-shadow: none;
    }
  }

  &:focus {
    outline: 2px solid var(--stone-color);
    outline-offset: 3px;
  }
}

.spirit-stone-caption {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.spirit-stone-emblem {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 1px solid color-mix(in srgb, var(--stone-color) 21%, transparent);
  border-radius: 5px;
  background: color-mix(in srgb, var(--stone-color) 9%, transparent);
  color: var(--stone-color);

  svg {
    width: 18px;
    height: 18px;
    stroke: currentColor;
    stroke-width: 1.1;
    stroke-linejoin: round;
  }

  .crystal-face {
    fill: currentColor;
    fill-opacity: 0.12;
  }

  .crystal-facets {
    fill: none;
  }
}

.spirit-stone-name {
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
}

.spirit-stone-value {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.spirit-stone-count {
  min-width: 0;
  color: var(--stone-color);
  font-size: 25px;
  font-weight: 600;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 20px color-mix(in srgb, var(--stone-color) clamp(0%, calc(18% * var(--glow-scale, 1)), 100%), transparent);
  overflow-wrap: anywhere;
}

.spirit-stone-unit {
  flex: none;
  color: var(--text-secondary);
  font-size: 11px;
}

@media (hover: hover) {
  .spirit-stone-summary:hover .spirit-stone-tag {
    border-color: color-mix(in srgb, var(--gold) 55%, transparent);
  }

  .spirit-stone-balance:not(.is-empty):hover {
    border-color: color-mix(in srgb, var(--stone-color) 58%, transparent);
    box-shadow: inset 0 1px 0 color-mix(in srgb, var(--stone-color) 24%, transparent);
  }
}

.items-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.item-strip {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: start;
  gap: 12px;
  padding: 12px 15px;
}

.item-emblem {
  position: relative;
  z-index: 2;
  width: 34px;
  height: 34px;
  margin-top: 1px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--tier-color) 32%, transparent);
  border-radius: var(--radius-sm, 8px);
  color: var(--tier-color);
  font-size: 13px;
}

.item-body {
  position: relative;
  z-index: 2;
  min-width: 0;
  display: grid;
  gap: 5px;
}

.item-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.item-title-group {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.item-name {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  letter-spacing: 0.025em;
  color: var(--text-primary);
}

.item-rank {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 8px;
  border: 1px solid color-mix(in srgb, var(--tier-color) 34%, transparent);
  border-radius: var(--radius-pill, 999px);
  font-size: 10.5px;
  font-weight: 600;
  color: var(--tier-color);
  background: color-mix(in srgb, var(--tier-color) 11%, transparent);
}

.item-count {
  flex: none;
  padding: 1px 8px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-raised) 72%, transparent);
  font-size: 11.5px;
  font-weight: 600;
  color: var(--gold-soft);
  font-variant-numeric: tabular-nums;
}

.item-desc {
  font-family: 'Noto Sans SC', 'MiSans', 'PingFang SC', 'Microsoft YaHei UI', sans-serif;
  font-size: 13.4px;
  font-weight: 450;
  line-height: 1.72;
  color: color-mix(in srgb, var(--text-primary) 80%, var(--text-secondary));
}

.empty-hint {
  padding: 18px 14px;
  border: 1px dashed var(--line-subtle);
  border-radius: var(--radius-md, 10px);
  background: color-mix(in srgb, var(--choice-surface) 45%, transparent);
  text-align: center;
  font-size: 12px;
  color: var(--text-secondary);
  opacity: 0.78;
}

@media screen and (max-width: 480px) {
  .spirit-stone-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .spirit-stone-balance {
    gap: 14px;
  }

  .spirit-stone-count {
    font-size: 23px;
  }
  .inventory-panel {
    gap: 18px;
  }

  .item-strip {
    grid-template-columns: 30px minmax(0, 1fr);
    gap: 9px;
    padding: 10px 12px;
  }

  .inventory-panel .item-strip.tier-immortal {
    padding-left: 15px;
  }

  .item-emblem {
    width: 30px;
    height: 30px;
    font-size: 11.5px;
  }

  .item-name {
    font-size: 14.5px;
  }

  .item-desc {
    font-size: 12.4px;
  }
}
