
.affairs-actions {
  color: var(--text-primary);
  margin-bottom: 28px;
}
.section-heading {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line-subtle);
}
h2 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  color: var(--text-accent);
  font:
    600 18px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  letter-spacing: 0.06em;
}
h2 i {
  color: var(--gold);
  font-size: 15px;
}
.count {
  margin-left: auto;
  color: var(--text-secondary);
  font-size: 12px;
}
.submit-mode-note {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 12px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.7;
}
.submit-mode-note.is-direct {
  color: var(--gold);
}
.submit-mode-note i {
  font-size: 11px;
}
.preferences {
  margin-top: 16px;
  padding-top: 10px;
  border-top: 1px solid color-mix(in srgb, var(--line-subtle) 70%, transparent);
  font-size: 12px;
}
summary {
  cursor: pointer;
  color: var(--text-secondary);
}
.preferences > summary {
  color: var(--gold);
}
.preferences-body {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 10px;
  padding: 13px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-md, 10px);
  background: var(--choice-surface, color-mix(in srgb, var(--surface-inset) 55%, transparent));
}
.preferences-body label:last-child {
  grid-column: 1 / -1;
}
label {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  color: var(--text-primary);
  line-height: 1.7;
}
input[type='checkbox'] {
  accent-color: var(--gold);
}
select {
  min-width: 0;
  padding: 6px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-sm, 6px);
  background: var(--surface-inset);
  color: var(--text-primary);
  font: inherit;
}
.situation {
  margin: 0 0 12px;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.85;
}
.tracked-label {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 13px;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: var(--gold);
  font-size: 12px;
  line-height: 1.6;
  text-align: left;
  cursor: pointer;
}
.turn-changes {
  margin: 0 0 12px;
  padding: 0;
  background: transparent;
}
.turn-changes summary {
  font-size: 12px;
}
.turn-changes button {
  display: grid;
  gap: 3px;
  width: 100%;
  padding: 8px 0 0;
  border: 0;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.7;
  text-align: left;
  cursor: pointer;
}
.turn-changes strong {
  color: var(--text-primary);
  font-weight: 500;
}
.action-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
}
.action-card {
  --choice-color: var(--gold);
  min-width: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--choice-color) 26%, var(--line-subtle));
  border-left: 3px solid color-mix(in srgb, var(--choice-color) 74%, var(--line-strong));
  border-radius: var(--radius-md, 10px);
  background:
    linear-gradient(115deg, color-mix(in srgb, var(--choice-color) 8%, transparent), transparent 62%),
    var(--choice-surface, var(--surface-inset));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--paper-highlight) 50%, transparent);
  transition:
    border-color 170ms ease,
    background 170ms ease,
    transform 170ms ease,
    box-shadow 170ms ease;
}
.action-card:hover:has(.action-choice:not(:disabled)) {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--choice-color) 54%, var(--line-strong));
  background:
    linear-gradient(115deg, color-mix(in srgb, var(--choice-color) 14%, transparent), transparent 68%),
    color-mix(in srgb, var(--choice-color) 6%, var(--choice-surface, var(--surface-inset)));
  box-shadow: 0 8px 22px color-mix(in srgb, var(--stage-shadow) 20%, transparent);
}
.type-探索 {
  --choice-color: var(--jade);
}
.type-交涉 {
  --choice-color: var(--gold);
}
.type-战斗 {
  --choice-color: var(--semantic-danger);
}
.type-修炼 {
  --choice-color: var(--semantic-info);
}
.type-整备 {
  --choice-color: var(--gold);
}
.type-亲密 {
  --choice-color: var(--semantic-relation);
}
.action-choice {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 12px 16px;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
}
.action-choice:focus-visible {
  outline: 2px solid var(--choice-color);
  outline-offset: -2px;
}
.action-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 1px solid color-mix(in srgb, var(--choice-color) 32%, transparent);
  border-radius: var(--radius-sm, 8px);
  background: color-mix(in srgb, var(--choice-color) 12%, var(--surface-raised));
  color: var(--choice-color);
  font-size: 12px;
}
.action-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
  line-height: 1.65;
  overflow-wrap: anywhere;
}
.action-copy strong {
  color: var(--text-primary);
  font:
    600 14px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  line-height: 1.5;
  letter-spacing: 0.03em;
}
.action-copy > span {
  color: var(--text-secondary);
  font-size: 12.5px;
}
.action-copy > .action-event {
  color: color-mix(in srgb, var(--choice-color) 65%, var(--text-primary));
}
.action-copy small {
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.6;
}
.action-type {
  padding: 2px 8px;
  border: 1px solid color-mix(in srgb, var(--choice-color) 30%, transparent);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--choice-color) 10%, transparent);
  color: var(--choice-color);
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.5;
  white-space: nowrap;
}
.action-choice > i {
  color: var(--choice-color);
  font-size: 11px;
  opacity: 0.72;
  transition: transform 0.16s ease, opacity 0.16s ease;
}
.action-card:hover .action-choice > i {
  opacity: 1;
  transform: translateX(2px);
}
.action-sources {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 14px 9px 54px;
}
.source-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--surface-raised) 68%, transparent);
  color: var(--text-secondary);
  font-size: 10.5px;
  line-height: 1.45;
  text-align: left;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease;

  i {
    color: var(--choice-color);
    font-size: 9px;
  }
  &:hover {
    color: var(--gold);
    border-color: var(--line-strong);
  }
}
.quick-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  margin-top: 14px;
}
.quick-actions button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border: 1px solid var(--line-subtle);
  border-radius: var(--radius-pill, 999px);
  background: color-mix(in srgb, var(--choice-surface) 74%, transparent);
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
  transition: all 0.16s ease;
}
.quick-actions button:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--gold) 40%, var(--line-subtle));
  color: var(--gold);
  background: var(--button-hover);
}
button:focus-visible,
summary:focus-visible,
select:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}
button:disabled {
  cursor: default;
  opacity: 0.5;
}
.quiet {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.9;
}
.inline {
  width: 100%;
  max-width: var(--reading-measure);
  margin: 24px auto 8px;
}
.inline-heading {
  display: grid;
  grid-template-columns: minmax(20px, 1fr) auto auto minmax(20px, 1fr);
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.heading-rule {
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--gold) 42%, var(--line-subtle)));
}
.heading-rule:last-child {
  transform: rotate(180deg);
}
.heading-title {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--gold);
  font:
    600 13px 'Noto Serif SC',
    'Songti SC',
    STSong,
    serif;
  letter-spacing: 0.12em;
}
.heading-note {
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.6;
}
.inline .action-list {
  gap: 9px;
}
.inline .action-choice {
  grid-template-columns: 30px minmax(0, 1fr) auto 12px;
  gap: 11px;
  padding: 11px 13px;
}
.inline .action-copy {
  gap: 3px;
  line-height: 1.65;
}
.inline .action-copy strong {
  font-size: 13.5px;
}
.inline .action-copy > span,
.inline .action-copy small {
  font-size: 12px;
}
.inline .action-type {
  font-size: 10px;
}
.inline .action-sources {
  padding: 0 13px 9px 54px;
}
@media (max-width: 760px) {
  .action-choice {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px 10px;
    padding: 12px 14px;
  }
  .action-type {
    justify-self: end;
  }
  .action-sources {
    padding-left: 14px;
  }
  .preferences-body {
    grid-template-columns: minmax(0, 1fr);
  }
  .inline .action-choice {
    grid-template-columns: 28px minmax(0, 1fr) 12px;
    padding: 10px 11px;
  }
  .inline .action-choice > i {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
  .inline .action-sources {
    padding-left: 48px;
  }
  .inline-heading {
    grid-template-columns: minmax(16px, 1fr) auto minmax(16px, 1fr);
    gap: 7px;
  }
  .heading-note {
    grid-column: 1 / -1;
    grid-row: 2;
    text-align: center;
  }
}
